  ["come across","우연히 발견하다","I came across an old photo.","옛날 사진 한 장을 우연히 발견했어."],
  ["cut down on","~을 줄이다","I'm trying to cut down on sugar.","설탕을 줄이려고 노력 중이야."],
  ["drop by","잠깐 들르다","I'll drop by after work.","퇴근 후에 잠깐 들를게."],
  ["end up","결국 ~하게 되다","We ended up staying home.","우리는 결국 집에 있었어."],
  ["get over","극복하다, 회복하다","It took me a while to get over it.","그걸 극복하는 데 시간이 좀 걸렸어."],
  ["give in","굴복하다, 양보하다","I finally gave in.","나 결국 포기하고 말았어."],
  ["go through","겪다, 살펴보다","She's going through a difficult time.","그녀는 힘든 시기를 겪고 있어."],
  ["hold on","기다리다, 꽉 잡다","Hold on. I'll check.","잠깐만. 확인해 볼게."],
  ["keep an eye on","지켜보다","Can you keep an eye on my bag?","내 가방 좀 봐줄래?"],
  ["leave out","빼놓다, 제외하다","You left out an important detail.","중요한 내용을 빠뜨렸어."],
  ["let down","실망시키다","I don't want to let you down.","너를 실망시키고 싶지 않아."],
  ["look forward to","~을 기대하다","I'm looking forward to the weekend.","주말이 기대돼."],
  ["make up for","만회하다, 보상하다","I'll make up for lost time.","놓친 시간을 만회할게."],
  ["pass out","기절하다, 나눠 주다","He almost passed out from the heat.","그는 더위 때문에 거의 기절할 뻔했어."],
  ["put up with","참다, 견디다","I can't put up with this noise.","이 소음을 더는 참을 수 없어."],
  ["run out of","~이 다 떨어지다","We've run out of milk.","우유가 다 떨어졌어."],
  ["set up","설치하다, 준비하다","Can you help me set up the computer?","컴퓨터 설치하는 것 좀 도와줄래?"],
  ["sort out","정리하다, 해결하다","We need to sort out this problem.","우리는 이 문제를 해결해야 해."],
  ["take over","인계받다, 장악하다","She will take over the project.","그녀가 그 프로젝트를 맡을 거야."],
  ["throw away","버리다","Don't throw away those papers.","그 서류들 버리지 마."],
  ["try on","입어 보다","Can I try this on?","이거 입어 봐도 돼?"],
  ["turn down","거절하다, 줄이다","He turned down the offer.","그는 그 제안을 거절했어."],
  ["turn up","나타나다, 소리를 높이다","She turned up late again.","그녀는 또 늦게 나타났어."],
  ["wake up","잠에서 깨다","I woke up earlier than usual.","평소보다 일찍 일어났어."],
  ["back up","백업하다, 지지하다","Make sure to back up your files.","파일을 꼭 백업해 둬."],
  ["break up","헤어지다, 분해하다","They decided to break up.","그들은 헤어지기로 했어."],
  ["check out","확인하다, 살펴보다","Check out this new café.","이 새 카페 한번 봐봐."],
  ["fill in","기입하다, 대신하다","Please fill in this form.","이 양식을 작성해 주세요."],
  ["get rid of","없애다, 버리다","I need to get rid of these old clothes.","이 낡은 옷들을 처분해야 해."],
  ["I messed up.","내가 망쳤어.","I messed up, and I'm sorry.","내가 망쳤어. 미안해."],
  ["It slipped my mind.","깜빡 잊었어.","I'm sorry. It completely slipped my mind.","미안해. 완전히 깜빡했어."],
  ["Let's get this over with.","이거 빨리 끝내자.","Let's get this over with and go home.","이거 빨리 끝내고 집에 가자."],
  ["I'm running out of time.","시간이 얼마 안 남았어.","I'm running out of time to finish this.","이걸 끝낼 시간이 얼마 안 남았어."],
  ["You can count on me.","나만 믿어.","Don't worry. You can count on me.","걱정 마. 나만 믿어."],
  ["It came out wrong.","말이 이상하게 나왔어.","Sorry, it came out wrong.","미안해, 말이 이상하게 나왔어."],
  ["Let's call it a day.","오늘은 여기까지 하자.","We've done enough. Let's call it a day.","충분히 했어. 오늘은 여기까지 하자."],
  ["I'll figure something out.","내가 어떻게든 방법을 찾아볼게.","Don't worry. I'll figure something out.","걱정 마. 내가 어떻게든 방법을 찾아볼게."],
  ["That should do it.","그 정도면 될 거야.","Add a little more water. That should do it.","물을 조금 더 넣어. 그 정도면 될 거야."]

  // DAY 06 - 자연스러운 대화
  ["Actually, now that I think about it...","그러고 보니 말이야...","Actually, now that I think about it, you're right.","그러고 보니 네 말이 맞아."],
  ["As far as I know","내가 아는 한","As far as I know, he's still here.","내가 알기로 그는 아직 여기 있어."],
  ["For some reason","왠지, 어떤 이유로","For some reason, I can't sleep.","왠지 잠이 안 와."],
  ["To be honest","솔직히 말해서","To be honest, I don't like it.","솔직히 말해서 난 그거 마음에 안 들어."],
  ["If you ask me","내 생각에는","If you ask me, it's too expensive.","내 생각에는 너무 비싸."],
  ["Come to think of it","생각해 보니","Come to think of it, I haven't seen her lately.","생각해 보니 요즘 그녀를 못 봤네."],
  ["In that case","그렇다면","In that case, let's leave early.","그렇다면 일찍 출발하자."],
  ["On the other hand","반면에","It's expensive. On the other hand, it's high quality.","비싸. 반면에 품질은 좋아."],
  ["At the same time","동시에","I was excited and nervous at the same time.","나는 동시에 신나면서도 긴장했어."],
  ["For the most part","대체로","For the most part, everything went well.","대체로 모든 일이 잘됐어."],
  ["It turns out that","알고 보니","It turns out that we went to the same school.","알고 보니 우리는 같은 학교에 다녔어."],
  ["As soon as possible","가능한 한 빨리","Please get back to me as soon as possible.","가능한 한 빨리 답변해 줘."],
  ["From time to time","가끔","I still think about it from time to time.","나는 아직도 가끔 그 일을 생각해."],
  ["Once in a while","이따금","We eat out once in a while.","우리는 가끔 외식해."],
  ["So far, so good.","지금까지는 좋아.","How's your new job? So far, so good.","새 직장은 어때? 지금까지는 좋아."],
  ["That being said","그렇긴 하지만","That being said, I still want to try.","그렇긴 하지만 그래도 해보고 싶어."],
  ["No wonder","어쩐지, 그럴 만도 하네","No wonder you're tired.","네가 피곤한 것도 당연하네."],
  ["What a coincidence!","정말 우연이다!","You're here too? What a coincidence!","너도 여기 있어? 정말 우연이다!"],
  ["I couldn't agree more.","전적으로 동의해.","I couldn't agree more. That's a great idea.","전적으로 동의해. 정말 좋은 생각이야."],
  ["You have a point.","네 말에도 일리가 있어.","You have a point. I hadn't thought of that.","네 말에도 일리가 있어. 그건 생각 못 했네."],
  ["That's beside the point.","그건 핵심에서 벗어난 얘기야.","That's beside the point. Let's focus.","그건 핵심에서 벗어난 얘기야. 집중하자."],
  ["Don't get me wrong.","오해하지 마.","Don't get me wrong. I like your idea.","오해하지 마. 네 아이디어 마음에 들어."],
  ["I'm not sure about that.","그건 잘 모르겠어.","I'm not sure about that. Let me think.","그건 잘 모르겠어. 생각해 볼게."],
  ["It never crossed my mind.","전혀 생각하지 못했어.","Honestly, it never crossed my mind.","솔직히 전혀 생각하지 못했어."],
  ["That's easier said than done.","말처럼 쉽지는 않아.","Changing habits is easier said than done.","습관을 바꾸는 건 말처럼 쉽지 않아."],
  ["You made my day.","덕분에 기분 좋은 하루가 됐어.","Your message really made my day.","네 메시지 덕분에 정말 기분 좋은 하루가 됐어."],
  ["I know what you mean.","무슨 말인지 알아.","I know what you mean. I've been there.","무슨 말인지 알아. 나도 그런 적 있어."],
  ["Don't sweat it.","걱정하지 마.","Don't sweat it. Everything is fine.","걱정하지 마. 다 괜찮아."],
  ["That's a good question.","좋은 질문이야.","That's a good question. I'm not sure.","좋은 질문이네. 나도 잘 모르겠어."],
  ["It happens.","그럴 수도 있지.","Don't be too hard on yourself. It happens.","너무 자책하지 마. 그럴 수도 있지."],
  ["I'm just curious.","그냥 궁금해서.","I'm just curious. Why did you choose that?","그냥 궁금해서 그런데, 왜 그걸 골랐어?"],
  ["Long story short","간단히 말하면","Long story short, we missed the train.","간단히 말하면 우리는 기차를 놓쳤어."],
  ["The thing is","문제는, 사실은","The thing is, I don't have enough time.","문제는 나한테 시간이 충분하지 않다는 거야."],
  ["It depends on the situation.","상황에 따라 달라.","It depends on the situation.","상황에 따라 달라."],
  ["I'm glad you brought that up.","그 얘기 꺼내 줘서 다행이야.","I'm glad you brought that up. I had a question.","그 얘기 꺼내 줘서 다행이야. 질문이 있었거든."],
  ["That's exactly what I was thinking.","나도 딱 그렇게 생각하고 있었어.","That's exactly what I was thinking!","나도 딱 그렇게 생각하고 있었어!"],
  ["I wouldn't go that far.","그 정도까지는 아니야.","I like him, but I wouldn't go that far.","그가 좋긴 하지만 그 정도까지는 아니야."],
  ["You never know until you try.","해보기 전에는 모르는 거야.","Just give it a chance. You never know until you try.","일단 한번 해봐. 해보기 전에는 모르는 거야."],
  ["Let's see how it goes.","어떻게 되는지 지켜보자.","We don't need to decide now. Let's see how it goes.","지금 결정할 필요 없어. 어떻게 되는지 지켜보자."],
  ["I'm all ears.","잘 듣고 있어, 말해 봐.","Tell me what happened. I'm all ears.","무슨 일이 있었는지 말해 봐. 잘 듣고 있어."]

  // DAY 07 - 상황별 실전 영어
  ["Could I get the menu?","메뉴판 주시겠어요?","Could I get the menu, please?","메뉴판 주시겠어요?"],
  ["I'd like to order.","주문할게요.","I'd like to order a sandwich.","샌드위치 하나 주문할게요."],
  ["Can I get this to go?","이거 포장해 주실 수 있나요?","Can I get this to go, please?","이거 포장해 주실 수 있나요?"],
  ["Could we get the check?","계산서 주시겠어요?","Could we get the check, please?","계산서 주시겠어요?"],
  ["I'm just looking.","그냥 둘러보는 중이에요.","Thanks, I'm just looking.","고마워요, 그냥 둘러보는 중이에요."],
  ["Do you have this in a different size?","이거 다른 사이즈도 있나요?","Do you have this in a larger size?","이거 더 큰 사이즈도 있나요?"],
  ["Can I try it on?","입어 봐도 될까요?","Can I try this jacket on?","이 재킷 입어 봐도 될까요?"],
  ["Where is the fitting room?","탈의실이 어디예요?","Excuse me, where is the fitting room?","실례합니다, 탈의실이 어디예요?"],
  ["How much is this?","이거 얼마예요?","Excuse me, how much is this?","실례합니다, 이거 얼마예요?"],
  ["Do you accept cards?","카드 받으시나요?","Do you accept credit cards?","신용카드 받으시나요?"],
  ["I have a reservation.","예약했어요.","Hi, I have a reservation under Kim.","안녕하세요, 김이라는 이름으로 예약했어요."],
  ["Could you take a picture of us?","저희 사진 좀 찍어 주실래요?","Could you take a picture of us, please?","저희 사진 좀 찍어 주실래요?"],
  ["How do I get there?","거기 어떻게 가나요?","How do I get to the station?","역까지 어떻게 가나요?"],
  ["Is it within walking distance?","걸어갈 수 있는 거리인가요?","Is the museum within walking distance?","박물관은 걸어갈 수 있는 거리인가요?"],
  ["I think I'm lost.","길을 잃은 것 같아요.","Excuse me, I think I'm lost.","실례합니다, 길을 잃은 것 같아요."],
  ["Which platform do I need?","몇 번 승강장으로 가야 하나요?","Which platform do I need for the train?","기차를 타려면 몇 번 승강장으로 가야 하나요?"],
  ["Is this seat taken?","여기 자리 있나요?","Excuse me, is this seat taken?","실례합니다, 여기 자리 있나요?"],
  ["Could you speak more slowly?","좀 더 천천히 말씀해 주시겠어요?","Could you speak more slowly, please?","좀 더 천천히 말씀해 주시겠어요?"],
  ["Could you say that again?","다시 말씀해 주시겠어요?","Sorry, could you say that again?","죄송하지만 다시 말씀해 주시겠어요?"],
  ["I didn't catch that.","잘 못 들었어요.","Sorry, I didn't catch that.","죄송해요, 잘 못 들었어요."],
  ["What does this mean?","이건 무슨 뜻인가요?","What does this word mean?","이 단어는 무슨 뜻인가요?"],
  ["How do you pronounce this?","이거 어떻게 발음하나요?","How do you pronounce this name?","이 이름은 어떻게 발음하나요?"],
  ["Could you help me with this?","이것 좀 도와주시겠어요?","Could you help me with this form?","이 양식 작성하는 것 좀 도와주시겠어요?"],
  ["I need some help.","도움이 필요해요.","Excuse me, I need some help.","실례합니다, 도움이 필요해요."],
  ["There's been a mistake.","실수가 있었어요.","I think there's been a mistake with my order.","주문에 실수가 있었던 것 같아요."],
  ["I'd like to make a complaint.","불만 사항을 말씀드리고 싶어요.","I'd like to make a complaint about the service.","서비스에 대해 불만을 말씀드리고 싶어요."],
  ["Could you check this for me?","이것 좀 확인해 주시겠어요?","Could you check this information for me?","이 정보 좀 확인해 주시겠어요?"],
  ["I need to change my booking.","예약을 변경해야 해요.","I need to change my hotel booking.","호텔 예약을 변경해야 해요."],
  ["Is there a pharmacy nearby?","근처에 약국이 있나요?","Excuse me, is there a pharmacy nearby?","실례합니다, 근처에 약국이 있나요?"],
  ["I don't feel well.","몸이 좋지 않아요.","I don't feel well today.","오늘 몸이 좋지 않아요."],
  ["I have a headache.","두통이 있어요.","I've had a headache since this morning.","오늘 아침부터 두통이 있어요."],
  ["Could you call a doctor?","의사를 불러 주시겠어요?","Could you call a doctor, please?","의사를 불러 주시겠어요?"],
  ["I'm allergic to peanuts.","저는 땅콩 알레르기가 있어요.","I'm allergic to peanuts, so I can't eat this.","저는 땅콩 알레르기가 있어서 이걸 먹을 수 없어요."],
  ["Could you recommend something?","뭔가 추천해 주시겠어요?","Could you recommend something popular?","인기 있는 걸 추천해 주시겠어요?"],
  ["I'm looking for this address.","이 주소를 찾고 있어요.","I'm looking for this address. Can you help me?","이 주소를 찾고 있어요. 도와주실 수 있나요?"],
  ["Would you mind waiting a moment?","잠시 기다려 주시겠어요?","Would you mind waiting a moment? I'll be right back.","잠시 기다려 주시겠어요? 금방 돌아올게요."],
  ["Could you give me a hand?","나 좀 도와줄래?","Could you give me a hand with these bags?","이 가방들 옮기는 것 좀 도와줄래?"],
  ["I'll be right back.","금방 돌아올게.","Stay here. I'll be right back.","여기 있어. 금방 돌아올게."],
  ["Thanks for letting me know.","알려 줘서 고마워.","Thanks for letting me know about the change.","변경 사항 알려 줘서 고마워."],
  ["Have a good one!","좋은 하루 보내세요!","Thanks for your help. Have a good one!","도와주셔서 감사합니다. 좋은 하루 보내세요!"]
  
  // DAY 08 - 사람과 관계
  ["relationship","관계","Communication is important in any relationship.","어떤 관계에서든 소통은 중요해."],
  ["colleague","동료","My colleagues are really friendly.","내 동료들은 정말 친절해."],
  ["neighbor","이웃","Our new neighbor seems nice.","우리 새 이웃은 괜찮은 사람 같아."],
  ["stranger","낯선 사람","I don't usually talk to strangers.","나는 보통 낯선 사람과 이야기하지 않아."],
  ["acquaintance","아는 사람, 지인","He's more of an acquaintance than a friend.","그는 친구라기보다는 아는 사람이야."],
  ["relative","친척","We're visiting some relatives this weekend.","이번 주말에 친척들을 방문할 거야."],
  ["personality","성격","We have completely different personalities.","우리는 성격이 완전히 달라."],
  ["behavior","행동","His behavior surprised everyone.","그의 행동은 모두를 놀라게 했어."],
  ["attitude","태도","I like her positive attitude.","나는 그녀의 긍정적인 태도가 좋아."],
  ["respect","존중하다, 존경","We should respect each other's opinions.","우리는 서로의 의견을 존중해야 해."],
  ["trust","신뢰하다","It takes time to build trust.","신뢰를 쌓는 데는 시간이 걸려."],
  ["support","지지하다, 지원하다","My family always supports me.","우리 가족은 항상 나를 지지해 줘."],
  ["apologize","사과하다","You should apologize to her.","그녀에게 사과하는 게 좋겠어."],
  ["forgive","용서하다","It took me a long time to forgive him.","그를 용서하는 데 오랜 시간이 걸렸어."],
  ["interrupt","방해하다, 말을 끊다","Sorry to interrupt you.","말 끊어서 미안해."],
  ["argue","말다툼하다, 주장하다","They argue about everything.","그들은 사소한 일로도 말다툼해."],
  ["misunderstand","오해하다","I think you misunderstood me.","네가 나를 오해한 것 같아."],
  ["compliment","칭찬하다, 칭찬","She gave me a nice compliment.","그녀가 나를 기분 좋게 칭찬해 줬어."],
  ["gossip","남의 이야기를 하다, 소문","I don't like gossip.","나는 남의 이야기를 하는 걸 좋아하지 않아."],
  ["reliable","믿을 만한","He's a very reliable person.","그는 정말 믿을 만한 사람이야."],
  ["thoughtful","사려 깊은","That was very thoughtful of you.","정말 배려 깊은 행동이었어."],
  ["considerate","배려심 있는","She's always considerate of others.","그녀는 항상 다른 사람들을 배려해."],
  ["outgoing","외향적인","My sister is more outgoing than me.","내 여동생은 나보다 더 외향적이야."],
  ["reserved","말수가 적은, 내성적인","He's quiet and a little reserved.","그는 조용하고 조금 내성적이야."],
  ["clingy","지나치게 의존하는","My dog gets clingy when I'm home.","우리 강아지는 내가 집에 있으면 계속 붙어 있으려고 해."],
  ["get to know","알아 가다","I'd like to get to know you better.","너를 더 알아 가고 싶어."],
  ["look up to","존경하다","I really look up to my older sister.","나는 언니를 정말 존경해."],
  ["look down on","깔보다","You shouldn't look down on others.","다른 사람을 깔보면 안 돼."],
  ["get together","함께 모이다","Let's get together sometime.","언제 한번 같이 만나자."],
  ["fall out","사이가 틀어지다","They fell out over a small argument.","그들은 사소한 말다툼으로 사이가 틀어졌어."],
  ["hit it off","처음부터 잘 통하다","We met yesterday and hit it off.","우리는 어제 만났는데 처음부터 잘 통했어."],
  ["catch up","밀린 이야기를 나누다","Let's catch up over coffee.","커피 마시면서 밀린 이야기 나누자."],
  ["keep in touch","연락을 계속하다","Let's keep in touch after graduation.","졸업하고도 계속 연락하자."],
  ["drift apart","서서히 멀어지다","We slowly drifted apart.","우리는 서서히 멀어졌어."],
  ["stand up for","옹호하다, 편들다","You should stand up for yourself.","자기 자신을 당당하게 지켜야 해."],
  ["I get along with her.","나는 그녀와 잘 지내.","I get along with everyone at work.","나는 직장에서 모두와 잘 지내."],
  ["We have a lot in common.","우리는 공통점이 많아.","We have a lot in common, especially music.","우리는 특히 음악에서 공통점이 많아."],
  ["He's not my type.","그는 내 취향이 아니야.","He's nice, but he's not my type.","그는 좋은 사람이지만 내 취향은 아니야."],
  ["I didn't mean to hurt you.","너에게 상처 주려던 건 아니야.","I'm sorry. I didn't mean to hurt you.","미안해. 너에게 상처 주려던 건 아니야."],
  ["We're on good terms.","우리는 사이가 좋아.","Even though we broke up, we're on good terms.","우리는 헤어졌지만 사이좋게 지내."]

  // DAY 09 - 일과 공부
  ["assignment","과제","I have an assignment due tomorrow.","내일 제출해야 하는 과제가 있어."],
  ["deadline","마감일","The deadline is next Friday.","마감일은 다음 주 금요일이야."],
  ["presentation","발표","I'm nervous about my presentation.","발표 때문에 긴장돼."],
  ["conference","회의, 학회","She's attending an international conference.","그녀는 국제 학회에 참석하고 있어."],
  ["project","프로젝트, 과제","We're working on a new project.","우리는 새로운 프로젝트를 진행하고 있어."],
  ["feedback","피드백, 의견","Thanks for your helpful feedback.","도움이 되는 피드백 고마워."],
  ["performance","성과, 수행","Her performance has improved a lot.","그녀의 성과가 많이 좋아졌어."],
  ["experience","경험","I learned a lot from that experience.","그 경험을 통해 많은 걸 배웠어."],
  ["opportunity","기회","This is a great opportunity for you.","이건 너에게 좋은 기회야."],
  ["responsibility","책임","It's my responsibility to finish this.","이걸 끝내는 건 내 책임이야."],
  ["concentrate","집중하다","I can't concentrate with all this noise.","이렇게 시끄러우면 집중할 수가 없어."],
  ["focus","집중하다, 초점","Let's focus on the main problem.","핵심 문제에 집중하자."],
  ["review","복습하다, 검토하다","I need to review what I learned.","배운 내용을 복습해야 해."],
  ["memorize","암기하다","I find it hard to memorize names.","나는 이름을 외우는 게 어려워."],
  ["practice","연습하다","You need to practice speaking every day.","매일 말하기를 연습해야 해."],
  ["improve","향상하다, 개선하다","I want to improve my English.","영어 실력을 향상하고 싶어."],
  ["participate","참여하다","Everyone is welcome to participate.","누구나 참여할 수 있어."],
  ["submit","제출하다","Please submit your report by Monday.","월요일까지 보고서를 제출해 주세요."],
  ["attend","참석하다","I have to attend a meeting this afternoon.","오늘 오후에 회의에 참석해야 해."],
  ["discuss","논의하다","We need to discuss this issue.","우리는 이 문제를 논의해야 해."],
  ["explain","설명하다","Could you explain that again?","그거 다시 설명해 주시겠어요?"],
  ["mention","언급하다","He didn't mention the price.","그는 가격에 대해 언급하지 않았어."],
  ["suggest","제안하다","She suggested a different approach.","그녀는 다른 접근법을 제안했어."],
  ["recommend","추천하다","Can you recommend a good book?","좋은 책 하나 추천해 줄래?"],
  ["solve","해결하다","We need to solve this problem together.","우리는 이 문제를 함께 해결해야 해."],
  ["analyze","분석하다","Let's analyze the results first.","먼저 결과를 분석하자."],
  ["research","조사하다, 연구","I'm researching different universities.","여러 대학을 조사하고 있어."],
  ["achieve","달성하다","You can achieve your goals with practice.","연습하면 목표를 달성할 수 있어."],
  ["struggle","애쓰다, 어려움을 겪다","I'm struggling with this assignment.","이 과제 때문에 애를 먹고 있어."],
  ["postpone","연기하다","We decided to postpone the meeting.","우리는 회의를 연기하기로 했어."],
  ["hand in","제출하다","Don't forget to hand in your homework.","숙제 제출하는 거 잊지 마."],
  ["look over","검토하다","Could you look over my essay?","내 에세이 좀 검토해 줄래?"],
  ["catch up on","밀린 것을 따라잡다","I need to catch up on my reading.","밀린 독서를 따라잡아야 해."],
  ["fall behind","뒤처지다","I don't want to fall behind in class.","수업에서 뒤처지고 싶지 않아."],
  ["come up with","생각해 내다","We need to come up with a solution.","우리는 해결책을 생각해 내야 해."],
  ["work on","~에 공을 들이다","I'm working on my pronunciation.","발음 연습에 집중하고 있어."],
  ["figure out how to","어떻게 ~할지 알아내다","I'm trying to figure out how to use this tool.","이 도구를 어떻게 사용하는지 알아내려고 해."],
  ["I'm swamped with work.","일이 너무 많아 정신없어.","I can't go out tonight. I'm swamped with work.","오늘 밤에는 못 나가. 일이 너무 많아."],
  ["I'll get back to you.","확인하고 다시 연락할게.","Let me check and I'll get back to you.","확인해 보고 다시 연락할게."],
  ["I'm making progress.","진전이 있어.","My speaking is slowly improving. I'm making progress.","말하기 실력이 조금씩 늘고 있어. 진전이 있어."]

  // DAY 10 - 생각과 의견
  ["opinion","의견","Everyone is entitled to their own opinion.","모든 사람은 자기 의견을 가질 권리가 있어."],
  ["perspective","관점","Try to see it from my perspective.","내 관점에서 한번 생각해 봐."],
  ["possibility","가능성","There's a possibility of rain tomorrow.","내일 비가 올 가능성이 있어."],
  ["evidence","증거","We need more evidence.","우리는 더 많은 증거가 필요해."],
  ["reason","이유","What's the reason for the delay?","지연된 이유가 뭐야?"],
  ["purpose","목적","What's the purpose of this meeting?","이 회의의 목적이 뭐야?"],
  ["benefit","이점, 혜택","Exercise has many health benefits.","운동은 건강에 많은 이점이 있어."],
  ["drawback","단점","The biggest drawback is the price.","가장 큰 단점은 가격이야."],
  ["advantage","장점","One advantage is that it's easy to use.","한 가지 장점은 사용하기 쉽다는 거야."],
  ["disadvantage","불리한 점, 단점","Every choice has its disadvantages.","모든 선택에는 단점이 있어."],
  ["issue","문제, 쟁점","We need to talk about this issue.","이 문제에 대해 이야기해야 해."],
  ["concern","걱정, 우려","My main concern is safety.","내 가장 큰 걱정은 안전이야."],
  ["factor","요인","Cost is an important factor.","비용은 중요한 요인이야."],
  ["impact","영향","Social media has a big impact on our lives.","소셜 미디어는 우리 삶에 큰 영향을 미쳐."],
  ["effect","효과, 영향","The medicine had no effect.","그 약은 효과가 없었어."],
  ["result","결과","We'll discuss the results tomorrow.","내일 결과를 논의할 거야."],
  ["consequence","결과, 여파","Every action has consequences.","모든 행동에는 결과가 따르지."],
  ["approach","접근법, 접근하다","We need a new approach.","우리는 새로운 접근법이 필요해."],
  ["option","선택지","We have several options.","우리에게는 몇 가지 선택지가 있어."],
  ["alternative","대안","Is there a cheaper alternative?","더 저렴한 대안이 있을까?"],
  ["likely","가능성이 높은","It's likely to rain tonight.","오늘 밤 비가 올 가능성이 높아."],
  ["unlikely","가능성이 낮은","It's unlikely that he'll agree.","그가 동의할 가능성은 낮아."],
  ["specific","구체적인","Can you give me a specific example?","구체적인 예를 들어 줄래?"],
  ["general","일반적인, 전반적인","I understand the general idea.","전반적인 내용은 이해했어."],
  ["accurate","정확한","Is this information accurate?","이 정보가 정확한가요?"],
  ["incorrect","틀린, 부정확한","Some of the information is incorrect.","정보 중 일부가 틀렸어."],
  ["relevant","관련 있는","That's not relevant to the topic.","그건 주제와 관련이 없어."],
  ["essential","필수적인","Sleep is essential for good health.","수면은 건강에 필수적이야."],
  ["complicated","복잡한","The situation is more complicated than it seems.","상황은 보기보다 더 복잡해."],
  ["straightforward","간단명료한","The instructions are pretty straightforward.","설명은 꽤 간단명료해."],
  ["consider","고려하다","We should consider all the options.","모든 선택지를 고려해야 해."],
  ["compare","비교하다","Let's compare the two products.","두 제품을 비교해 보자."],
  ["evaluate","평가하다","We need time to evaluate the results.","결과를 평가할 시간이 필요해."],
  ["determine","결정하다, 알아내다","It's difficult to determine the cause.","원인을 알아내기 어려워."],
  ["indicate","나타내다, 가리키다","The results indicate a clear improvement.","결과는 뚜렷한 개선을 보여 줘."],
  ["suggestion","제안","That's a helpful suggestion.","도움이 되는 제안이야."],
  ["I have mixed feelings about it.","그것에 대해 마음이 복잡해.","I have mixed feelings about moving abroad.","해외로 이사하는 것에 대해 마음이 복잡해."],
  ["There's no point in arguing.","논쟁해 봐야 소용없어.","We've made our decision. There's no point in arguing.","우리는 이미 결정했어. 논쟁해 봐야 소용없어."],
  ["It makes a difference.","그건 차이를 만들어.","A little practice every day makes a difference.","매일 조금씩 연습하는 게 차이를 만들어."],
  ["That's not necessarily true.","그게 꼭 사실인 건 아니야.","That's not necessarily true in every case.","모든 경우에 그게 꼭 사실인 건 아니야."]

  // DAY 11 - 자주 쓰는 동사
  ["avoid","피하다","I try to avoid eating late at night.","밤늦게 먹는 걸 피하려고 해."],
  ["prevent","막다, 예방하다","This can help prevent accidents.","이것은 사고를 예방하는 데 도움이 돼."],
  ["allow","허락하다","My parents don't allow me to stay out late.","부모님은 내가 늦게까지 밖에 있는 걸 허락하지 않아."],
  ["require","필요로 하다, 요구하다","This job requires experience.","이 일에는 경험이 필요해."],
  ["provide","제공하다","The hotel provides free breakfast.","그 호텔은 무료 아침 식사를 제공해."],
  ["include","포함하다","The price includes breakfast.","가격에 아침 식사가 포함되어 있어."],
  ["involve","포함하다, 수반하다","The job involves working with children.","그 일은 아이들과 함께 일하는 것을 포함해."],
  ["depend","의존하다, 달려 있다","It depends on how much time we have.","우리가 시간이 얼마나 있는지에 달려 있어."],
  ["expect","기대하다, 예상하다","What do you expect me to do?","내가 뭘 하길 바라는 거야?"],
  ["realize","깨닫다","I didn't realize how late it was.","시간이 이렇게 늦은 줄 몰랐어."],
  ["recognize","알아보다, 인식하다","I didn't recognize him at first.","처음에는 그를 알아보지 못했어."],
  ["respond","응답하다","She hasn't responded to my message.","그녀는 내 메시지에 아직 답하지 않았어."],
  ["react","반응하다","How did he react to the news?","그는 그 소식에 어떻게 반응했어?"],
  ["affect","영향을 미치다","Lack of sleep affects my mood.","수면 부족은 내 기분에 영향을 줘."],
  ["influence","영향을 주다","Friends can influence your decisions.","친구들은 네 결정에 영향을 줄 수 있어."],
  ["encounter","마주치다, 맞닥뜨리다","We encountered a few problems.","우리는 몇 가지 문제에 부딪혔어."],
  ["establish","설립하다, 확립하다","They established a new company.","그들은 새 회사를 설립했어."],
  ["maintain","유지하다","It's important to maintain a healthy lifestyle.","건강한 생활 방식을 유지하는 게 중요해."],
  ["increase","증가하다, 늘리다","Prices continue to increase.","가격이 계속 오르고 있어."],
  ["decrease","감소하다, 줄이다","We need to decrease our expenses.","지출을 줄여야 해."],
  ["expand","확장하다","The company plans to expand overseas.","그 회사는 해외로 확장할 계획이야."],
  ["reduce","줄이다","I'm trying to reduce my screen time.","화면 보는 시간을 줄이려고 해."],
  ["replace","대체하다","We need to replace the old equipment.","오래된 장비를 교체해야 해."],
  ["recommend","추천하다","I highly recommend this movie.","이 영화 정말 추천해."],
  ["suggest","제안하다","I suggest taking a short break.","잠깐 쉬는 걸 제안해."],
  ["admit","인정하다","I admit that I was wrong.","내가 틀렸다는 걸 인정해."],
  ["deny","부인하다","He denied breaking the window.","그는 창문을 깬 사실을 부인했어."],
  ["refuse","거절하다","She refused to answer the question.","그녀는 질문에 답하기를 거부했어."],
  ["accept","받아들이다, 수락하다","I accepted the invitation.","초대를 받아들였어."],
  ["achieve","성취하다","She achieved her dream.","그녀는 꿈을 이뤘어."],
  ["handle","다루다, 처리하다","Can you handle this situation?","이 상황을 처리할 수 있겠어?"],
  ["deal with","대처하다, 다루다","I don't know how to deal with stress.","스트레스에 어떻게 대처해야 할지 모르겠어."],
  ["come up","발생하다, 떠오르다","Something urgent came up.","급한 일이 생겼어."],
  ["bring about","초래하다, 일으키다","The change brought about positive results.","그 변화는 긍정적인 결과를 가져왔어."],
  ["carry out","수행하다","They carried out an experiment.","그들은 실험을 수행했어."],
  ["point out","지적하다","She pointed out a mistake in my report.","그녀는 내 보고서의 실수를 지적했어."],
  ["take into account","고려하다","We should take your opinion into account.","네 의견을 고려해야 해."],
  ["make sure","확인하다, 확실히 하다","Make sure you lock the door.","문 잠그는 거 꼭 확인해."],
  ["keep in mind","명심하다","Keep in mind that things take time.","일에는 시간이 걸린다는 걸 명심해."],
  ["It doesn't hurt to ask.","물어본다고 손해 볼 건 없어.","It doesn't hurt to ask for help.","도움을 요청한다고 손해 볼 건 없어."]

  // DAY 12 - 자연스러운 원어민 표현
  ["I'm down.","나 좋아, 나 할래.","You want to get pizza? I'm down.","피자 먹으러 갈래? 나 좋아."],
  ["I'm good.","난 괜찮아, 됐어.","Would you like more coffee? I'm good, thanks.","커피 더 드릴까요? 괜찮아요, 감사합니다."],
  ["No worries.","괜찮아, 걱정 마.","No worries. It happens.","괜찮아. 그럴 수도 있지."],
  ["My bad.","내 실수야, 내가 잘못했어.","My bad. I sent the wrong file.","내 실수야. 잘못된 파일을 보냈어."],
  ["You bet.","물론이지, 당연하지.","Can you help me? You bet!","도와줄 수 있어? 당연하지!"],
  ["I'm beat.","나 완전히 지쳤어.","I'm beat. I'm going straight to bed.","나 완전히 지쳤어. 바로 자러 갈 거야."],
  ["I'm broke.","나 돈이 거의 없어.","I can't go shopping. I'm broke.","쇼핑하러 못 가. 나 돈이 거의 없어."],
  ["That's on me.","그건 내 책임이야, 내가 낼게.","Don't worry about the bill. That's on me.","계산은 걱정하지 마. 내가 낼게."],
  ["It's on the house.","이건 서비스예요.","The dessert is on the house.","디저트는 서비스예요."],
  ["I'm in.","나도 할래, 나 참여할게.","We're going hiking this weekend. I'm in!","이번 주말에 등산 갈 거야. 나도 갈래!"],
  ["I'm out.","난 빠질게.","You guys can go ahead. I'm out.","너희끼리 가. 난 빠질게."],
  ["Count me in.","나도 끼워 줘.","If you're planning a trip, count me in.","여행 계획하는 거면 나도 끼워 줘."],
  ["I'm not buying it.","난 그 말 안 믿어.","He said he forgot, but I'm not buying it.","그는 잊어버렸다고 했지만 난 안 믿어."],
  ["Give it a shot.","한번 시도해 봐.","You've got nothing to lose. Give it a shot.","잃을 것도 없잖아. 한번 해봐."],
  ["I'm all for it.","난 완전 찬성이야.","A weekend trip? I'm all for it.","주말 여행? 난 완전 찬성이야."],
  ["That's the spirit!","바로 그런 자세야!","Don't give up. That's the spirit!","포기하지 마. 바로 그런 자세야!"],
  ["Way to go!","잘했어!","You passed the test? Way to go!","시험에 합격했다고? 잘했어!"],
  ["Lucky you!","너 운 좋다!","You got free tickets? Lucky you!","무료 티켓을 받았다고? 너 운 좋다!"],
  ["What a relief!","정말 다행이다!","The test is over. What a relief!","시험이 끝났어. 정말 다행이다!"],
  ["It rings a bell.","어디서 들어 본 것 같아.","That name rings a bell.","그 이름 어디서 들어 본 것 같아."],
  ["I'm not following.","무슨 말인지 잘 모르겠어.","Sorry, I'm not following. Could you explain?","미안한데 무슨 말인지 잘 모르겠어. 설명해 줄래?"],
  ["You lost me.","무슨 말인지 모르겠어.","You lost me after the first sentence.","첫 문장 다음부터 무슨 말인지 모르겠어."],
  ["Fair point.","일리 있는 말이야.","Fair point. I hadn't considered that.","일리 있는 말이야. 그건 생각 못 했어."],
  ["I'm with you.","네 말에 동의해, 이해해.","I understand your idea. I'm with you.","네 생각 이해해. 나도 동의해."],
  ["It's a long shot.","성공 가능성이 희박해.","Getting tickets now is a long shot.","지금 티켓을 구하는 건 가능성이 희박해."],
  ["Fingers crossed!","잘되길 빌자!","I hope I get the job. Fingers crossed!","취직했으면 좋겠다. 잘되길 빌자!"],
  ["Don't push it.","무리하지 마, 적당히 해.","You've already had two desserts. Don't push it.","디저트 두 개나 먹었잖아. 적당히 해."],
  ["Take it easy.","쉬엄쉬엄해, 편하게 해.","You've been working hard. Take it easy.","열심히 일했잖아. 좀 쉬어."],
  ["I'm not kidding.","농담 아니야.","I'm not kidding. It was really scary.","농담 아니야. 정말 무서웠어."],
  ["You wish!","꿈 깨!","You think I'll do your homework? You wish!","내가 네 숙제를 해줄 거라고 생각해? 꿈 깨!"],
  ["That's so random.","진짜 뜬금없다.","Why did you ask that? That's so random.","왜 그런 걸 물어봐? 진짜 뜬금없다."],
  ["I'm over it.","이제 신경 안 써, 다 극복했어.","We had an argument, but I'm over it now.","우리가 말다툼했지만 이제 괜찮아."],
  ["It is what it is.","어쩔 수 없지, 그런 거지.","We can't change the past. It is what it is.","과거는 바꿀 수 없어. 어쩔 수 없지."],
  ["Don't even bother.","아예 신경 쓰지 마, 애쓰지 마.","Don't even bother explaining. I understand.","굳이 설명하려고 하지 마. 이해해."],
  ["I'm getting there.","점점 나아지고 있어.","My English isn't perfect, but I'm getting there.","내 영어가 완벽하진 않지만 점점 나아지고 있어."],
  ["That's a first.","이런 건 처음이네.","He actually arrived early. That's a first.","그가 정말 일찍 도착했어. 이런 건 처음이네."],
  ["You read my mind.","내 마음을 읽었네.","I was just about to suggest pizza. You read my mind.","막 피자를 제안하려던 참이었어. 내 마음을 읽었네."],
  ["Let's not jump to conclusions.","성급하게 결론 내리지 말자.","We don't know the whole story. Let's not jump to conclusions.","전체 이야기를 모르잖아. 성급하게 결론 내리지 말자."],
  ["I'm just messing with you.","그냥 장난치는 거야.","Relax! I'm just messing with you.","진정해! 그냥 장난치는 거야."]
  
  // DAY 13 - 일상에서 자주 쓰는 단어
  ["ordinary","평범한","It was just an ordinary day.","그냥 평범한 하루였어."],
  ["typical","전형적인, 흔한","That's a typical mistake.","그건 흔히 하는 실수야."],
  ["usual","평소의, 보통의","I'll take my usual coffee.","늘 마시던 커피로 할게."],
  ["common","흔한, 공통의","That's a common problem.","그건 흔한 문제야."],
  ["simple","간단한, 단순한","Let's keep it simple.","간단하게 하자."],
  ["complicated","복잡한","It's more complicated than I thought.","생각보다 복잡해."],
  ["comfortable","편안한","These shoes are comfortable.","이 신발은 편해."],
  ["convenient","편리한","Online shopping is convenient.","온라인 쇼핑은 편리해."],
  ["available","이용 가능한, 시간이 되는","Are you available tomorrow?","내일 시간 돼?"],
  ["necessary","필요한","Is it really necessary?","그게 정말 필요해?"],
  ["possible","가능한","Is it possible to change the date?","날짜를 바꾸는 게 가능해?"],
  ["impossible","불가능한","Nothing is impossible.","불가능한 건 없어."],
  ["similar","비슷한","Our tastes are similar.","우리는 취향이 비슷해."],
  ["different","다른","Things are different now.","이제 상황이 달라졌어."],
  ["exact","정확한","What's the exact time?","정확히 몇 시야?"],
  ["specific","구체적인, 특정한","Can you give me a specific example?","구체적인 예를 들어 줄래?"],
  ["general","일반적인","I have a general idea.","대략적인 생각은 있어."],
  ["recent","최근의","Have you seen any recent movies?","최근에 영화 본 거 있어?"],
  ["current","현재의","What's your current job?","지금 무슨 일 해?"],
  ["future","미래","I'm excited about the future.","미래가 기대돼."],
  ["past","과거","Let's not talk about the past.","과거 이야기는 하지 말자."],
  ["present","현재","Try to enjoy the present.","현재를 즐기려고 해 봐."],
  ["local","현지의, 지역의","I'd like to try local food.","현지 음식을 먹어 보고 싶어."],
  ["foreign","외국의","I've never tried foreign food.","외국 음식은 먹어 본 적 없어."],
  ["public","공공의, 대중의","It's a public place.","공공장소야."],
  ["private","개인적인","That's a private matter.","그건 개인적인 문제야."],
  ["personal","개인적인","Can I ask you a personal question?","개인적인 질문 하나 해도 돼?"],
  ["special","특별한","Today is a special day.","오늘은 특별한 날이야."],
  ["normal","정상적인, 보통의","Is this normal?","이게 정상인 거야?"],
  ["strange","이상한, 낯선","Something feels strange.","뭔가 이상한 느낌이 들어."],
  ["serious","심각한, 진지한","Are you serious?","진심이야?"],
  ["obvious","명백한","The answer is obvious.","답은 뻔해."],
  ["familiar","익숙한","Your face looks familiar.","너 얼굴이 낯익어."],
  ["unusual","평소와 다른, 특이한","That's unusual for him.","그 사람치고는 특이하네."],
  ["perfect","완벽한","The timing was perfect.","타이밍이 완벽했어."],
  ["excellent","훌륭한","You did an excellent job.","정말 훌륭하게 해냈어."],
  ["terrible","끔찍한, 형편없는","I had a terrible day.","오늘 정말 최악이었어."],
  ["awful","끔찍한","The weather is awful.","날씨가 정말 끔찍해."],
  ["amazing","놀라운","The view was amazing.","경치가 정말 놀라웠어."],
  ["incredible","믿기 힘든","That's incredible!","정말 믿기지 않아!"]

  // DAY 14 - 감정과 성격
  ["confident","자신감 있는","I feel more confident now.","이제 자신감이 좀 생겼어."],
  ["shy","수줍은","I was shy as a child.","어렸을 때는 수줍음이 많았어."],
  ["honest","솔직한, 정직한","I'll be honest with you.","너한테 솔직하게 말할게."],
  ["patient","참을성 있는","You need to be patient.","참을성을 가져야 해."],
  ["careful","조심하는","Be careful on your way home.","집에 갈 때 조심해."],
  ["careless","부주의한","That was a careless mistake.","그건 부주의한 실수였어."],
  ["polite","예의 바른","He's always polite to everyone.","그는 항상 모두에게 예의 바르게 행동해."],
  ["rude","무례한","That sounded a little rude.","그 말은 조금 무례하게 들렸어."],
  ["kind","친절한","She's always kind to me.","그녀는 항상 나에게 친절해."],
  ["selfish","이기적인","Don't be so selfish.","너무 이기적으로 굴지 마."],
  ["generous","관대한, 후한","He's generous with his time.","그는 시간을 아끼지 않고 사람들에게 써."],
  ["stubborn","고집 센","My brother is really stubborn.","우리 형은 정말 고집이 세."],
  ["lazy","게으른","I'm too lazy to cook today.","오늘은 요리하기 너무 귀찮아."],
  ["active","활동적인","She's very active on weekends.","그녀는 주말에 정말 활동적이야."],
  ["quiet","조용한","I prefer quiet places.","나는 조용한 곳이 좋아."],
  ["outgoing","외향적인","He's friendly and outgoing.","그는 친근하고 외향적이야."],
  ["independent","독립적인","She wants to be independent.","그녀는 독립적이고 싶어 해."],
  ["responsible","책임감 있는","He's responsible for the project.","그가 그 프로젝트를 책임지고 있어."],
  ["creative","창의적인","That's a creative idea.","정말 창의적인 생각이야."],
  ["curious","호기심 많은","Kids are naturally curious.","아이들은 원래 호기심이 많아."],
  ["sensitive","예민한, 민감한","I'm sensitive to noise.","나는 소리에 민감해."],
  ["emotional","감정적인","I'm feeling emotional today.","오늘은 감정이 좀 복잡해."],
  ["mature","성숙한","That was a mature decision.","그건 성숙한 결정이었어."],
  ["jealous","질투하는","I was a little jealous.","나 조금 질투했어."],
  ["embarrassed","당황스러운, 창피한","I was so embarrassed.","나 정말 창피했어."],
  ["disappointed","실망한","I'm disappointed in myself.","나 자신에게 실망했어."],
  ["frustrated","답답한, 좌절한","I'm getting frustrated.","점점 답답해지고 있어."],
  ["relieved","안도한","I'm relieved to hear that.","그 말을 들으니 안심이야."],
  ["grateful","감사하는","I'm grateful for your help.","네 도움에 감사해."],
  ["lonely","외로운","I feel lonely sometimes.","가끔 외로워."],
  ["guilty","죄책감을 느끼는","I feel guilty about it.","그 일 때문에 죄책감이 들어."],
  ["ashamed","부끄러운","You have nothing to be ashamed of.","부끄러워할 필요 없어."],
  ["nervous","긴장한","I'm nervous about the interview.","면접 때문에 긴장돼."],
  ["thrilled","매우 신나는","I'm thrilled about the news.","그 소식에 정말 신나."],
  ["furious","몹시 화가 난","She was absolutely furious.","그녀는 정말 몹시 화가 났어."],
  ["miserable","비참한, 몹시 불행한","I felt miserable yesterday.","어제는 정말 기분이 엉망이었어."],
  ["content","만족하는","I'm content with my life.","나는 내 삶에 만족해."],
  ["hopeful","희망적인","I'm hopeful about the future.","미래에 희망을 갖고 있어."],
  ["insecure","자신감이 부족한, 불안한","I sometimes feel insecure.","가끔 자신감이 없어져."],
  ["relaxed","느긋한, 편안한","I feel relaxed at home.","집에 있으면 마음이 편해."],
  ["motivated","의욕이 있는","I feel motivated to study.","공부하고 싶은 의욕이 생겨."]

  // DAY 15 - 행동과 생활 동사
  ["admit","인정하다","I admit that I was wrong.","내가 틀렸다는 걸 인정해."],
  ["afford","~할 여유가 있다","I can't afford a new car.","새 차를 살 여유가 없어."],
  ["announce","발표하다","They announced the results.","그들은 결과를 발표했어."],
  ["apologize","사과하다","You should apologize to her.","그녀에게 사과해야 해."],
  ["appreciate","고마워하다, 진가를 알아보다","I really appreciate your support.","네 응원에 정말 감사해."],
  ["argue","말다툼하다, 주장하다","We argued about money.","우리는 돈 문제로 다퉜어."],
  ["arrange","정리하다, 준비하다","I'll arrange everything.","내가 모든 걸 준비할게."],
  ["attend","참석하다","I have to attend a meeting.","회의에 참석해야 해."],
  ["belong","속하다","This bag belongs to me.","이 가방은 내 거야."],
  ["cancel","취소하다","I had to cancel my plans.","계획을 취소해야 했어."],
  ["celebrate","축하하다","Let's celebrate your success.","네 성공을 축하하자."],
  ["complain","불평하다","He's always complaining.","그는 항상 불평해."],
  ["concentrate","집중하다","I can't concentrate right now.","지금은 집중이 안 돼."],
  ["consider","고려하다","I'll consider your suggestion.","네 제안을 고려해 볼게."],
  ["convince","설득하다","You don't have to convince me.","나를 설득할 필요 없어."],
  ["decide","결정하다","I haven't decided yet.","아직 결정 안 했어."],
  ["depend","의존하다, 달려 있다","It depends on the weather.","날씨에 달려 있어."],
  ["deserve","~할 자격이 있다","You deserve a break.","너도 쉴 자격이 있어."],
  ["discover","발견하다","I discovered a great little cafe.","정말 좋은 작은 카페를 발견했어."],
  ["encourage","격려하다","My parents encouraged me.","부모님이 나를 격려해 주셨어."],
  ["establish","설립하다, 확립하다","They established a new company.","그들은 새 회사를 설립했어."],
  ["examine","살펴보다, 검사하다","The doctor examined my eyes.","의사가 내 눈을 검사했어."],
  ["exist","존재하다","Does life exist on other planets?","다른 행성에도 생명체가 존재할까?"],
  ["expand","확장하다","The business is expanding.","사업이 확장되고 있어."],
  ["explain","설명하다","Can you explain it again?","다시 설명해 줄래?"],
  ["express","표현하다","It's hard to express my feelings.","내 감정을 표현하기가 어려워."],
  ["focus","집중하다","Let's focus on the main issue.","핵심 문제에 집중하자."],
  ["handle","다루다, 처리하다","I can handle this myself.","이건 내가 직접 처리할 수 있어."],
  ["hesitate","망설이다","Don't hesitate to ask.","부담 갖지 말고 물어봐."],
  ["ignore","무시하다","Just ignore the comments.","그냥 댓글은 무시해."],
  ["imagine","상상하다","Can you imagine living there?","거기서 사는 걸 상상할 수 있어?"],
  ["improve","개선하다, 나아지다","My English is improving.","내 영어가 늘고 있어."],
  ["include","포함하다","The price includes breakfast.","가격에 아침 식사가 포함돼 있어."],
  ["increase","증가하다, 늘리다","We need to increase sales.","매출을 늘려야 해."],
  ["influence","영향을 주다","Friends can influence your choices.","친구들은 네 선택에 영향을 줄 수 있어."],
  ["involve","포함하다, 관련시키다","The job involves a lot of travel.","그 일은 출장이 많아."],
  ["manage","관리하다, 해내다","I managed to finish it.","어떻게든 그걸 끝냈어."],
  ["mention","언급하다","You didn't mention that before.","아까는 그 얘기 안 했잖아."],
  ["notice","알아차리다","Did you notice anything unusual?","뭔가 이상한 점 알아챘어?"],
  ["offer","제안하다, 제공하다","They offered me a job.","그들은 나에게 일자리를 제안했어."],
  ["organize","정리하다, 조직하다","I need to organize my room.","방을 정리해야 해."]

  // DAY 16 - 사람과 사회
  ["audience","청중, 관객","The audience loved the show.","관객들은 그 공연을 정말 좋아했어."],
  ["customer","고객","The customer asked for a refund.","고객이 환불을 요청했어."],
  ["employee","직원","The company has fifty employees.","그 회사에는 직원이 50명 있어."],
  ["employer","고용주","My employer is very supportive.","우리 고용주는 지원을 잘해 줘."],
  ["manager","관리자, 매니저","I need to speak to the manager.","매니저와 이야기해야 해."],
  ["owner","주인","Who's the owner of this shop?","이 가게 주인이 누구야?"],
  ["guest","손님, 게스트","We have a guest tonight.","오늘 밤 손님이 와."],
  ["host","주최자, 진행자","She was a wonderful host.","그녀는 정말 훌륭한 주최자였어."],
  ["stranger","낯선 사람","Don't talk to strangers.","낯선 사람과 이야기하지 마."],
  ["relative","친척","I'm visiting my relatives this weekend.","이번 주말에 친척들을 만나러 가."],
  ["couple","커플, 두 사람","They're a lovely couple.","그들은 정말 잘 어울리는 커플이야."],
  ["crowd","군중, 사람들","There was a huge crowd.","사람들이 엄청 많이 모였어."],
  ["community","지역 사회, 공동체","It's a close community.","서로 친밀한 공동체야."],
  ["society","사회","Technology is changing society.","기술이 사회를 바꾸고 있어."],
  ["culture","문화","I'd like to learn about your culture.","네 문화에 대해 배우고 싶어."],
  ["tradition","전통","It's a family tradition.","우리 가족의 전통이야."],
  ["generation","세대","Different generations think differently.","세대마다 생각이 달라."],
  ["citizen","시민","Every citizen has rights.","모든 시민은 권리가 있어."],
  ["neighboring","이웃한","We visited a neighboring town.","우리는 인근 마을을 방문했어."],
  ["leader","지도자","She's a natural leader.","그녀는 타고난 리더야."],
  ["member","회원, 구성원","I'm a member of the club.","나는 그 동아리 회원이야."],
  ["partner","파트너, 동반자","I work well with my partner.","나는 파트너와 호흡이 잘 맞아."],
  ["volunteer","자원봉사자","She works as a volunteer.","그녀는 자원봉사자로 일해."],
  ["expert","전문가","You should ask an expert.","전문가에게 물어보는 게 좋아."],
  ["beginner","초보자","I'm still a beginner.","나는 아직 초보자야."],
  ["professional","전문가, 직업적인","You should act like a professional.","전문가답게 행동해야 해."],
  ["individual","개인","Every individual is different.","사람마다 다 달라."],
  ["relationship","관계","Trust is important in a relationship.","관계에서는 신뢰가 중요해."],
  ["behavior","행동","His behavior was inappropriate.","그의 행동은 부적절했어."],
  ["attitude","태도","I like your positive attitude.","네 긍정적인 태도가 마음에 들어."],
  ["character","성격, 인물","She has a strong character.","그녀는 성격이 강해."],
  ["reputation","평판","The restaurant has a good reputation.","그 식당은 평판이 좋아."],
  ["respect","존중","We should treat each other with respect.","우리는 서로 존중하며 대해야 해."],
  ["trust","신뢰","Trust takes time to build.","신뢰를 쌓는 데는 시간이 걸려."],
  ["support","지원, 지지","Thank you for your support.","응원해 줘서 고마워."],
  ["advice","조언","Can I give you some advice?","내가 조언 하나 해도 될까?"],
  ["permission","허락","You need permission to enter.","들어가려면 허락이 필요해."],
  ["opportunity","기회","This is a great opportunity.","이건 정말 좋은 기회야."],
  ["experience","경험","It was a valuable experience.","정말 값진 경험이었어."],
  ["responsibility","책임","That's not my responsibility.","그건 내 책임이 아니야."],
  ["involvement","참여, 관여","Her involvement made a difference.","그녀의 참여가 변화를 만들었어."]

  // DAY 17 - 자연스러운 실전 표현
  ["That makes sense.","말이 되네, 이해돼","Oh, that makes sense now.","아, 이제 이해가 되네."],
  ["I see what you mean.","무슨 말인지 알겠어","I see what you mean, but I disagree.","무슨 말인지 알겠지만 동의하진 않아."],
  ["That's a good point.","좋은 지적이야","That's a good point. I hadn't thought of that.","좋은 지적이야. 그건 생각 못 했네."],
  ["I'm not sure about that.","그건 잘 모르겠어","I'm not sure about that idea.","그 생각은 잘 모르겠어."],
  ["Let me think about it.","생각해 볼게","Let me think about it for a minute.","잠깐 생각해 볼게."],
  ["It slipped my mind.","깜빡했어","Sorry, it completely slipped my mind.","미안, 완전히 깜빡했어."],
  ["I didn't see that coming.","그럴 줄 몰랐어","Wow, I didn't see that coming.","와, 그럴 줄은 몰랐어."],
  ["You never know.","모르는 일이야","You never know what might happen.","무슨 일이 생길지 모르는 거야."],
  ["It's up to you.","네가 결정해","We can go now or later. It's up to you.","지금 가도 되고 나중에 가도 돼. 네가 정해."],
  ["I'm on my way.","가는 중이야","I'm on my way. See you soon.","가는 중이야. 곧 봐."],
  ["Give me a second.","잠깐만","Give me a second. I'll be right back.","잠깐만. 금방 돌아올게."],
  ["No rush.","급할 거 없어","Take your time. No rush.","천천히 해. 급할 거 없어."],
  ["I'm running late.","늦고 있어","I'm running late because of traffic.","차가 막혀서 늦고 있어."],
  ["That works for me.","난 괜찮아","Friday at six? That works for me.","금요일 6시? 난 괜찮아."],
  ["Sounds good to me.","난 좋아","Let's meet at the cafe. Sounds good to me.","카페에서 만나자. 난 좋아."],
  ["I'm just looking.","그냥 둘러보는 중이에요","Thanks, I'm just looking.","고마워요, 그냥 둘러보는 중이에요."],
  ["Can I get a receipt?","영수증 받을 수 있을까요?","Can I get a receipt, please?","영수증 받을 수 있을까요?"],
  ["Could you do me a favor?","부탁 하나 해도 될까요?","Could you do me a favor?","부탁 하나 해도 될까요?"],
  ["I owe you one.","신세 졌어","Thanks for helping me. I owe you one.","도와줘서 고마워. 신세 졌어."],
  ["It's not worth it.","그럴 가치가 없어","Don't argue with him. It's not worth it.","그와 다투지 마. 그럴 가치 없어."],
  ["I'm used to it.","익숙해졌어","The long commute doesn't bother me. I'm used to it.","긴 통근도 괜찮아. 익숙해졌거든."],
  ["I'm getting the hang of it.","점점 익숙해지고 있어","This game is hard, but I'm getting the hang of it.","이 게임 어렵지만 점점 익숙해지고 있어."],
  ["I can't complain.","불평할 건 없어, 그럭저럭 괜찮아","How's work? I can't complain.","일은 어때? 그럭저럭 괜찮아."],
  ["It's been a while.","오랜만이야","It's been a while since we last met.","우리 마지막으로 만난 지 꽤 됐네."],
  ["What a coincidence!","정말 우연이다!","You're here too? What a coincidence!","너도 여기 있어? 정말 우연이다!"],
  ["I'm just kidding.","농담이야","Don't take it seriously. I'm just kidding.","심각하게 받아들이지 마. 농담이야."],
  ["You can say that again.","내 말이 그 말이야","This week has been exhausting. You can say that again.","이번 주 정말 지쳤어. 내 말이 그 말이야."],
  ["That's not the point.","그게 핵심이 아니야","That's not the point I'm trying to make.","내가 말하려는 핵심은 그게 아니야."],
  ["For what it's worth.","도움이 될지는 모르겠지만","For what it's worth, I think you did great.","도움이 될지는 모르겠지만 난 네가 잘했다고 생각해."],
  ["I'm all set.","난 준비됐어, 이제 괜찮아","Thanks, I'm all set.","고마워요, 이제 괜찮아요."],
  ["It doesn't matter.","상관없어","Choose whichever one you like. It doesn't matter.","네가 좋아하는 걸 골라. 상관없어."],
  ["That's exactly what I thought.","내가 딱 그렇게 생각했어","That's exactly what I thought when I saw it.","그걸 봤을 때 나도 딱 그렇게 생각했어."],
  ["I couldn't agree more.","정말 전적으로 동의해","I couldn't agree more with you.","네 말에 정말 전적으로 동의해."],
  ["Don't get me wrong.","오해하지 마","Don't get me wrong. I like the idea.","오해하지 마. 난 그 생각이 마음에 들어."],
  ["I'm afraid so.","유감이지만 그런 것 같아","Is the store closed? I'm afraid so.","가게 문 닫았어? 유감이지만 그런 것 같아."],
  ["I'm afraid not.","유감이지만 아닌 것 같아","Can we still make it? I'm afraid not.","우리 아직 시간 맞출 수 있어? 유감이지만 어려울 것 같아."],
  ["That depends.","그건 상황에 따라 달라","Are you coming? That depends.","올 거야? 상황에 따라 달라."],
  ["I'll keep that in mind.","명심할게","Thanks for the tip. I'll keep that in mind.","팁 고마워. 명심할게."],
  ["It's worth a try.","시도해 볼 만해","Why not? It's worth a try.","왜 안 되겠어? 시도해 볼 만해."],
  ["Let's call it a day.","오늘은 이만 마무리하자","We've done enough. Let's call it a day.","충분히 했어. 오늘은 이만 마무리하자."]
  
