  // DAY 37 - 자연스러운 일상 표현
  ["That makes sense.","말이 되네, 이해돼","Oh, that makes sense now.","아, 이제 이해돼."],
  ["I see what you mean.","무슨 말인지 알겠어","I see what you mean about the schedule.","일정에 관해 무슨 말인지 알겠어."],
  ["That's not the point.","그게 핵심이 아니야","That's not the point I'm trying to make.","내가 말하려는 핵심은 그게 아니야."],
  ["It depends.","상황에 따라 달라","It depends on the weather.","날씨에 따라 달라."],
  ["I'm not sure about that.","그건 잘 모르겠어","I'm not sure about that idea.","그 생각은 잘 모르겠어."],
  ["You have a point.","일리 있는 말이야","You have a point, actually.","네 말도 일리가 있네."],
  ["Fair enough.","그럴 만하네, 인정","Fair enough. I understand your decision.","그럴 만하네. 네 결정을 이해해."],
  ["No wonder.","어쩐지, 그럴 만도 하네","No wonder you're so tired.","어쩐지 네가 그렇게 피곤하더라."],
  ["Come to think of it.","그러고 보니","Come to think of it, I haven't called her.","그러고 보니 그녀에게 전화한 적이 없네."],
  ["As far as I know.","내가 알기로는","As far as I know, the store is closed.","내가 알기로는 그 가게는 문을 닫았어."],
  ["For the most part.","대체로, 대부분","For the most part, everything went well.","대체로 모든 일이 잘 진행됐어."],
  ["At least.","적어도, 최소한","At least we gave it a try.","적어도 우리는 한번 시도해 봤잖아."],
  ["Not necessarily.","꼭 그런 건 아니야","Expensive doesn't necessarily mean better.","비싸다고 꼭 더 좋은 건 아니야."],
  ["If anything.","오히려, 굳이 말하자면","If anything, I feel more confident now.","오히려 지금은 더 자신감이 생겼어."],
  ["In other words.","다시 말해서","In other words, we need more time.","다시 말해서 시간이 더 필요하다는 거야."],
  ["To be honest.","솔직히 말하면","To be honest, I didn't enjoy it.","솔직히 말하면 그게 즐겁지 않았어."],
  ["Believe it or not.","믿기 어렵겠지만","Believe it or not, I used to hate coffee.","믿기 어렵겠지만 예전에는 커피를 싫어했어."],
  ["That reminds me.","그 말 들으니 생각났어","That reminds me, I need to buy milk.","그 말 들으니 우유를 사야 한다는 게 생각났어."],
  ["I'm all ears.","잘 듣고 있어, 말해 봐","Go ahead. I'm all ears.","계속 말해 봐. 잘 듣고 있어."],
  ["It's up to you.","네가 결정해","We can eat here or outside. It's up to you.","여기서 먹어도 되고 밖에서 먹어도 돼. 네가 결정해."],
  ["I'm on my way.","가는 중이야","I'm on my way. I'll be there soon.","가는 중이야. 곧 도착할게."],
  ["Take your time.","천천히 해","There's no rush. Take your time.","급할 거 없어. 천천히 해."],
  ["Don't get me wrong.","오해하지 마","Don't get me wrong. I like your idea.","오해하지 마. 네 생각이 마음에 들어."],
  ["It slipped my mind.","깜빡했어","Sorry, it completely slipped my mind.","미안해, 완전히 깜빡했어."],
  ["I'm used to it.","이제 익숙해","The long commute doesn't bother me. I'm used to it.","긴 통근도 괜찮아. 이제 익숙해."],
  ["I'm getting there.","점점 나아지고 있어","My English isn't perfect, but I'm getting there.","영어가 완벽하진 않지만 점점 나아지고 있어."],
  ["That rings a bell.","어디서 들어본 것 같아","That name rings a bell.","그 이름 어디서 들어본 것 같아."],
  ["It's worth a try.","시도해 볼 만해","Why not? It's worth a try.","왜 안 해 보겠어? 시도해 볼 만해."],
  ["I'm just saying.","그냥 하는 말이야","I'm not criticizing you. I'm just saying.","널 비판하는 게 아니야. 그냥 하는 말이야."],
  ["You never know.","어떻게 될지 모르는 거야","Give it a chance. You never know.","한번 기회를 줘 봐. 어떻게 될지 모르는 거잖아."],
  ["That's a relief.","다행이다","The test results were normal. That's a relief.","검사 결과가 정상이래. 다행이다."],
  ["It happens.","그럴 수도 있지","Don't worry about the mistake. It happens.","실수했다고 걱정하지 마. 그럴 수도 있지."],
  ["I'm not buying it.","난 그 말을 믿지 않아","His excuse sounds strange. I'm not buying it.","그의 변명이 이상해. 난 믿지 않아."],
  ["Let's see how it goes.","어떻게 되는지 지켜보자","We don't need to decide now. Let's see how it goes.","지금 결정할 필요 없어. 어떻게 되는지 지켜보자."],
  ["I'm down for that.","나도 좋아, 나도 할래","A movie tonight? I'm down for that.","오늘 밤 영화 보자고? 나도 좋아."],
  ["Sounds like a plan.","좋은 생각이야","Let's meet at six. Sounds like a plan.","6시에 만나자. 좋은 생각이야."],
  ["I couldn't agree more.","전적으로 동의해","I couldn't agree more with your opinion.","네 의견에 전적으로 동의해."],
  ["Don't push yourself.","무리하지 마","You've been working all day. Don't push yourself.","하루 종일 일했잖아. 무리하지 마."],
  ["It's no big deal.","별일 아니야","Don't apologize. It's no big deal.","사과하지 마. 별일 아니야."],
  ["I'll keep that in mind.","명심할게","Thanks for the advice. I'll keep that in mind.","조언 고마워. 명심할게."]
  
