  ["dumbbell","덤벨","Start with lighter dumbbells.","더 가벼운 덤벨로 시작해."],
  ["barbell","바벨","He lifted a heavy barbell.","그는 무거운 바벨을 들어 올렸어."],
  ["resistance","저항","Resistance bands are useful for training.","저항 밴드는 운동에 유용해."],
  ["athlete","운동선수","The athlete trained every day.","그 운동선수는 매일 훈련했어."],
  ["coach","코치, 지도하다","Our coach gave us useful advice.","코치가 우리에게 유용한 조언을 해 줬어."],
  ["teammate","팀 동료","I trust my teammates.","나는 팀 동료들을 믿어."],
  ["opponent","상대 선수","Our opponent was very strong.","우리 상대 선수는 정말 강했어."],
  ["tournament","토너먼트, 대회","She's competing in an international tournament.","그녀는 국제 대회에 출전하고 있어."],
  ["championship","선수권 대회","They won the national championship.","그들은 전국 선수권 대회에서 우승했어."],
  ["referee","심판","The referee stopped the match.","심판이 경기를 중단시켰어."],
  ["penalty","벌칙, 페널티","The team received a penalty.","그 팀은 페널티를 받았어."],
  ["scoreboard","점수판","Check the scoreboard for the latest score.","최신 점수는 점수판을 확인해."],
  ["defeat","패배시키다, 패배","Our team defeated the champions.","우리 팀이 우승팀을 이겼어."],
  ["victory","승리","The victory made everyone proud.","그 승리는 모두를 자랑스럽게 만들었어."],
  ["defensive","수비의, 방어적인","The team played defensively.","그 팀은 수비적으로 경기했어."],
  ["offensive","공격의, 공격적인","They switched to an offensive strategy.","그들은 공격 전략으로 전환했어."]

  // DAY 41 - 공부와 사고력
  ["academic","학업의, 학문적인","She has excellent academic results.","그녀는 학업 성적이 아주 좋아."],
  ["scholarship","장학금","He received a full scholarship.","그는 전액 장학금을 받았어."],
  ["semester","학기","The new semester starts next week.","새 학기는 다음 주에 시작해."],
  ["curriculum","교육 과정","The curriculum includes practical projects.","교육 과정에는 실습 프로젝트가 포함돼 있어."],
  ["lecture","강의","I attended an interesting lecture.","흥미로운 강의에 참석했어."],
  ["seminar","세미나","The seminar focuses on environmental issues.","그 세미나는 환경 문제에 초점을 맞춰."],
  ["workshop","실습 수업, 워크숍","I joined a creative writing workshop.","창작 글쓰기 워크숍에 참여했어."],
  ["assignment","과제","I finished my assignment early.","과제를 일찍 끝냈어."],
  ["thesis","논문, 학위 논문","She's writing her master's thesis.","그녀는 석사 논문을 쓰고 있어."],
  ["research","연구하다, 연구","More research is needed.","더 많은 연구가 필요해."],
  ["hypothesis","가설","The experiment supported our hypothesis.","그 실험은 우리의 가설을 뒷받침했어."],
  ["evidence","증거","There's no evidence to support the claim.","그 주장을 뒷받침할 증거가 없어."],
  ["theory","이론","The theory explains how the system works.","그 이론은 시스템이 어떻게 작동하는지 설명해."],
  ["concept","개념","It's a difficult concept to understand.","이해하기 어려운 개념이야."],
  ["principle","원리, 원칙","The principle is simple.","원리는 간단해."],
  ["method","방법","We tried a different method.","우리는 다른 방법을 시도했어."],
  ["approach","접근법","I like your approach to learning.","나는 네 학습 접근법이 마음에 들어."],
  ["perspective","관점","Try to see it from another perspective.","다른 관점에서 바라보도록 해."],
  ["assumption","가정, 추정","That's based on a false assumption.","그건 잘못된 가정에 근거하고 있어."],
  ["reasoning","추론, 논리적 사고","Her reasoning was clear and logical.","그녀의 추론은 명확하고 논리적이었어."],
  ["logic","논리","I don't understand the logic behind it.","그것에 담긴 논리를 이해하지 못하겠어."],
  ["conclusion","결론","We reached the same conclusion.","우리는 같은 결론에 도달했어."],
  ["insight","통찰, 이해","The book gave me valuable insight.","그 책은 나에게 귀중한 통찰을 줬어."],
  ["interpretation","해석","There are several interpretations of the poem.","그 시에는 여러 가지 해석이 있어."],
  ["comprehension","이해력","Reading regularly improves comprehension.","꾸준히 읽으면 이해력이 향상돼."],
  ["concentration","집중력","I need silence for better concentration.","집중력을 높이려면 조용해야 해."],
  ["attention span","집중 지속 시간","My attention span gets shorter when I'm tired.","피곤하면 집중 지속 시간이 짧아져."],
  ["memorize","암기하다","I find it difficult to memorize names.","나는 이름을 외우는 게 어려워."],
  ["recall","기억해 내다","I can't recall where I put my keys.","열쇠를 어디에 뒀는지 기억이 안 나."],
  ["review","복습하다, 검토하다","Review your notes before the test.","시험 전에 필기를 복습해."],
  ["revise","수정하다, 복습하다","I need to revise my essay.","에세이를 수정해야 해."],
  ["comprehend","이해하다","It's easier to comprehend with examples.","예시가 있으면 더 쉽게 이해할 수 있어."],
  ["distinguish","구별하다","Can you distinguish fact from opinion?","사실과 의견을 구별할 수 있어?"],
  ["classify","분류하다","The samples were classified into groups.","표본은 여러 그룹으로 분류됐어."],
  ["infer","추론하다","We can infer the meaning from the context.","문맥을 통해 의미를 추론할 수 있어."],
  ["deduce","추론하다, 연역하다","What can you deduce from these facts?","이 사실들로부터 무엇을 추론할 수 있어?"],
  ["speculate","추측하다","It's too early to speculate about the cause.","원인을 추측하기에는 아직 너무 일러."],
  ["question","의문을 제기하다","It's healthy to question your assumptions.","자신의 가정에 의문을 제기하는 건 좋은 일이야."],
  ["reflect","곰곰이 생각하다","Take a moment to reflect on your experience.","잠시 시간을 내서 네 경험을 되돌아봐."],
  ["contemplate","숙고하다","She sat quietly, contemplating her future.","그녀는 조용히 앉아 자신의 미래를 깊이 생각했어."]

  // DAY 42 - 자연스러운 고급 표현
  ["That being said,","그렇긴 하지만","That being said, I still think we should try.","그렇긴 하지만 그래도 시도해 봐야 한다고 생각해."],
  ["On the contrary,","반대로, 오히려","On the contrary, I found it quite enjoyable.","오히려 나는 그게 꽤 즐거웠어."],
  ["In the meantime,","그동안, 그 사이에","I'll prepare dinner. In the meantime, you can relax.","내가 저녁을 준비할게. 그동안 너는 쉬어도 돼."],
  ["By all means.","물론이지, 얼마든지","Can I use your phone? By all means.","네 휴대전화 써도 돼? 물론이지."],
  ["For what it's worth,","도움이 될지는 모르겠지만","For what it's worth, I think you did well.","도움이 될지는 모르겠지만 네가 잘했다고 생각해."],
  ["Needless to say,","말할 필요도 없이","Needless to say, safety comes first.","말할 필요도 없이 안전이 최우선이야."],
  ["To some extent,","어느 정도는","I agree with you to some extent.","어느 정도는 네 말에 동의해."],
  ["In the long run,","장기적으로 보면","In the long run, this will save us money.","장기적으로 보면 이건 우리 돈을 아껴 줄 거야."],
  ["For the time being,","당분간은","Let's stay here for the time being.","당분간은 여기 머물자."],
  ["At the same time,","동시에, 한편으로는","I was excited and nervous at the same time.","나는 동시에 설레면서도 긴장했어."],
  ["In particular,","특히","I enjoy outdoor activities, in particular hiking.","나는 야외 활동, 특히 등산을 즐겨."],
  ["To put it simply,","간단히 말하면","To put it simply, we need a better plan.","간단히 말하면 더 나은 계획이 필요해."],
  ["As a matter of fact,","사실은","As a matter of fact, I've met him before.","사실 나는 그를 전에 만난 적이 있어."],
  ["That said,","그렇지만","That said, we shouldn't give up yet.","그렇지만 아직 포기하면 안 돼."],
  ["In the first place,","애초에, 우선","Why did you agree in the first place?","애초에 왜 동의한 거야?"],
  ["For instance,","예를 들어","For instance, you could start with a short walk.","예를 들어 짧게 산책하는 것부터 시작할 수 있어."],
  ["In contrast,","대조적으로","In contrast, the second option is much cheaper.","대조적으로 두 번째 선택지는 훨씬 저렴해."],
  ["Regardless of,","~와 관계없이","I'll support you regardless of the outcome.","결과와 관계없이 널 지지할게."],
  ["As a result,","그 결과","As a result, we had to change our plans.","그 결과 우리는 계획을 바꿔야 했어."],
  ["In the first place","애초에","I shouldn't have gone there in the first place.","애초에 거기에 가지 말았어야 했어."],
  ["That's beside the point.","그건 논점에서 벗어난 이야기야","That's beside the point. We need a solution.","그건 논점에서 벗어난 이야기야. 해결책이 필요해."],
  ["I'm afraid so.","안타깝지만 그런 것 같아","Is the event canceled? I'm afraid so.","행사가 취소됐어? 안타깝지만 그런 것 같아."],
  ["I'm afraid not.","안타깝지만 아닌 것 같아","Can you come tomorrow? I'm afraid not.","내일 올 수 있어? 안타깝지만 어려울 것 같아."],
  ["It goes without saying.","말할 것도 없어","It goes without saying that practice matters.","연습이 중요하다는 건 말할 것도 없어."],
  ["You can say that again.","내 말이 그 말이야","This week has been exhausting. You can say that again.","이번 주 정말 지쳤어. 내 말이 그 말이야."],
  ["I'm in two minds about it.","그 일에 대해 마음이 반반이야","I'm in two minds about moving abroad.","해외로 이사하는 것에 대해 마음이 반반이야."],
  ["It's easier said than done.","말처럼 쉽지는 않아","Changing habits is easier said than done.","습관을 바꾸는 건 말처럼 쉽지 않아."],
  ["Let's get straight to the point.","본론으로 바로 들어가자","We don't have much time, so let's get straight to the point.","시간이 많지 않으니 본론으로 바로 들어가자."],
  ["I wouldn't go that far.","그 정도까지는 아니라고 생각해","I like the movie, but I wouldn't go that far.","그 영화가 좋긴 하지만 그 정도까지는 아니야."],
  ["That's a different story.","그건 또 다른 이야기야","I can help you today. Tomorrow is a different story.","오늘은 도와줄 수 있어. 내일은 또 다른 이야기야."],
  ["It doesn't hurt to ask.","물어봐서 나쁠 건 없어","You might get a discount. It doesn't hurt to ask.","할인을 받을 수도 있잖아. 물어봐서 나쁠 건 없어."],
  ["I'm not in the mood.","그럴 기분이 아니야","I'm not in the mood to go out tonight.","오늘 밤은 외출할 기분이 아니야."],
  ["Don't take it personally.","개인적으로 받아들이지 마","He talks that way to everyone. Don't take it personally.","그는 모두에게 그렇게 말해. 개인적으로 받아들이지 마."],
  ["I'm torn between the two.","둘 중에서 고민돼","I'm torn between studying and getting some sleep.","공부할지 잠을 좀 잘지 고민돼."],
  ["It's not set in stone.","확정된 건 아니야","The schedule isn't set in stone yet.","일정은 아직 확정된 게 아니야."],
  ["Let's play it by ear.","상황을 봐 가며 결정하자","We don't need a strict plan. Let's play it by ear.","엄격한 계획은 필요 없어. 상황을 봐 가며 결정하자."],
  ["I have mixed feelings about it.","그것에 대해 복잡한 마음이 들어","I have mixed feelings about leaving my hometown.","고향을 떠나는 것에 대해 마음이 복잡해."],
  ["It slipped through the cracks.","빠뜨리고 놓쳤어","The important detail slipped through the cracks.","중요한 세부 사항을 빠뜨리고 놓쳤어."],
  ["I'm leaning toward the first option.","첫 번째 선택지 쪽으로 마음이 기울고 있어","I'm leaning toward the first option because it's simpler.","더 간단하기 때문에 첫 번째 선택지 쪽으로 마음이 기울고 있어."],
  ["Let's not jump to conclusions.","성급하게 결론 내리지 말자","We don't know the whole story. Let's not jump to conclusions.","전체 이야기를 모르잖아. 성급하게 결론 내리지 말자."]

