  // DAY 67 - 자연스러운 고급 표현
  ["I'm not buying it.","난 그 말을 안 믿어.","He says he forgot, but I'm not buying it.","그는 잊어버렸다고 하지만 난 그 말을 안 믿어."],
  ["You can say that again.","내 말이 그 말이야.","This week has been exhausting. You can say that again.","이번 주 정말 지쳤어. 내 말이 그 말이야."],
  ["I'm torn between the two.","둘 중 어느 쪽을 선택할지 고민돼.","I'm torn between staying home and going out.","집에 있을지 외출할지 고민돼."],
  ["It caught me off guard.","전혀 예상하지 못했어.","Her question caught me off guard.","그녀의 질문은 나를 완전히 당황하게 했어."],
  ["I didn't see that coming.","그건 예상 못 했어.","The ending was shocking. I didn't see that coming.","결말이 충격적이었어. 전혀 예상 못 했어."],
  ["I'm not in the mood.","그럴 기분이 아니야.","I'm not in the mood to talk right now.","지금은 이야기할 기분이 아니야."],
  ["It's a long story.","말하자면 길어.","Why did you leave? It's a long story.","왜 떠났냐고? 말하자면 길어."],
  ["I couldn't care less.","전혀 신경 안 써.","What they think? I couldn't care less.","그 사람들이 어떻게 생각하든 난 전혀 신경 안 써."],
  ["That's easier said than done.","말이 쉽지.","Getting over someone is easier said than done.","누군가를 잊는 건 말처럼 쉽지 않아."],
  ["I'm all ears.","잘 듣고 있어, 말해 봐.","Tell me what happened. I'm all ears.","무슨 일이 있었는지 말해 봐. 잘 듣고 있어."],
  ["It's driving me crazy.","정말 미치게 하네.","This constant noise is driving me crazy.","이 끊임없는 소음이 정말 미치게 하네."],
  ["I'm at a loss.","어떻게 해야 할지 모르겠어.","I'm at a loss for words.","무슨 말을 해야 할지 모르겠어."],
  ["That went better than expected.","생각보다 잘됐어.","The interview went better than expected.","면접이 생각보다 잘됐어."],
  ["I have a lot on my plate.","할 일이 너무 많아.","I can't take on another project. I have a lot on my plate.","프로젝트를 더 맡을 수 없어. 할 일이 너무 많아."],
  ["Let's get this over with.","이거 빨리 끝내자.","Let's get this over with and go home.","이거 빨리 끝내고 집에 가자."],
  ["I'm having second thoughts.","다시 생각하게 돼, 마음이 바뀌려 해.","I'm having second thoughts about buying it.","그걸 사는 것에 대해 다시 생각하고 있어."],
  ["It slipped through the cracks.","실수로 누락됐어.","The important detail slipped through the cracks.","중요한 세부 사항이 실수로 누락됐어."],
  ["I'm on the fence.","아직 결정하지 못했어.","I'm on the fence about joining the club.","그 동아리에 가입할지 아직 결정하지 못했어."],
  ["Let's call it even.","이걸로 서로 퉁치자.","You helped me last time, so let's call it even.","지난번에 네가 도와줬으니 이걸로 서로 퉁치자."],
  ["I wouldn't mind.","난 괜찮아, 기꺼이 할 수 있어.","I wouldn't mind going for a walk.","산책하러 가도 난 괜찮아."]

