  // DAY 100 - 고급 회화와 표현
  ["That's not necessarily true.","그게 꼭 사실인 건 아니야.","That's not necessarily true in every situation.","모든 상황에서 그게 꼭 사실인 건 아니야."],
  ["I see where you're coming from.","네 입장이 이해돼.","I see where you're coming from, but I disagree.","네 입장은 이해하지만 동의하지는 않아."],
  ["Let's agree to disagree.","서로 의견이 다른 채로 두자.","We have different opinions, so let's agree to disagree.","우리는 의견이 다르니 서로 다름을 인정하자."],
  ["I'm inclined to agree.","동의하는 편이야.","I'm inclined to agree with your suggestion.","네 제안에 동의하는 편이야."],
  ["I beg to differ.","제 생각은 다릅니다.","I beg to differ on that particular point.","그 부분에 대해서는 제 생각이 다릅니다."],
  ["That's a fair assessment.","타당한 평가야.","I think that's a fair assessment of the situation.","그 상황에 대한 타당한 평가라고 생각해."],
  ["For the most part","대체로","For the most part, the project went smoothly.","대체로 프로젝트는 순조롭게 진행됐어."],
  ["In the long run","장기적으로 보면","In the long run, this will save us money.","장기적으로 보면 이게 우리 돈을 아껴 줄 거야."],
  ["At the end of the day","결국","At the end of the day, your health matters most.","결국 네 건강이 가장 중요해."],
  ["That being said","그렇긴 하지만","That being said, we still have a lot to learn.","그렇긴 하지만 우리는 아직 배울 게 많아."],
  ["Having said that","그렇다고 해도","Having said that, I understand your concerns.","그렇다고 해도 네 우려는 이해해."],
  ["On second thought","다시 생각해 보니","On second thought, let's stay home tonight.","다시 생각해 보니 오늘 밤은 집에 있자."],
  ["Come to think of it","생각해 보니","Come to think of it, I haven't seen her lately.","생각해 보니 최근에 그녀를 못 봤네."],
  ["If anything","오히려","If anything, the situation has improved.","오히려 상황이 나아졌어."],
  ["By all means","물론이지, 얼마든지","By all means, feel free to ask questions.","물론이죠. 편하게 질문하세요."],
  ["As a last resort","최후의 수단으로","We can ask for help as a last resort.","최후의 수단으로 도움을 요청할 수 있어."],
  ["For better or worse","좋든 나쁘든","For better or worse, things have changed.","좋든 나쁘든 상황은 변했어."],
  ["To some degree","어느 정도","I agree with you to some degree.","어느 정도 네 의견에 동의해."],
  ["In hindsight","돌이켜 보면","In hindsight, I should have waited.","돌이켜 보면 기다렸어야 했어."],
  ["Without a doubt","의심할 여지 없이","She's without a doubt the best candidate.","그녀는 의심할 여지 없이 최고의 후보야."],
  ["Needless to say","말할 필요도 없이","Needless to say, everyone was surprised.","말할 필요도 없이 모두가 놀랐어."],
  ["That goes without saying.","그건 말할 필요도 없어.","Your safety comes first. That goes without saying.","네 안전이 우선이야. 그건 말할 필요도 없어."],
  ["I wouldn't say that.","그렇게 말하진 않겠어.","I wouldn't say that he's lazy.","그가 게으르다고 말하진 않겠어."],
  ["That's open to interpretation.","해석하기 나름이야.","Whether it's fair is open to interpretation.","그게 공정한지는 해석하기 나름이야."],
  ["There's more to it than that.","그게 전부는 아니야.","There's more to the story than that.","그 이야기에는 그 이상의 내용이 있어."],
  ["It's a matter of time.","시간문제일 뿐이야.","It's only a matter of time before they find out.","그들이 알아내는 건 시간문제일 뿐이야."],
  ["That's beside the issue.","그건 쟁점과 별개의 문제야.","That's beside the issue we're discussing.","그건 우리가 논의하는 쟁점과 별개의 문제야."],
  ["I wouldn't rule it out.","그 가능성을 배제하지는 않겠어.","I wouldn't rule it out just yet.","아직 그 가능성을 배제하지는 않겠어."],
  ["There's no denying that.","그건 부정할 수 없어.","There's no denying that she's talented.","그녀가 재능 있다는 건 부정할 수 없어."],
  ["It's not as simple as it sounds.","말처럼 간단한 문제가 아니야.","Finding a solution isn't as simple as it sounds.","해결책을 찾는 건 말처럼 간단한 문제가 아니야."],
  ["I'm leaning toward this option.","이 선택지 쪽으로 마음이 기울고 있어.","I'm leaning toward this option for now.","일단은 이 선택지 쪽으로 마음이 기울고 있어."],
  ["That's a different story.","그건 또 다른 이야기야.","I like the idea, but making it work is a different story.","아이디어는 좋지만 실제로 실행하는 건 또 다른 이야기야."],
  ["It goes both ways.","서로 마찬가지야.","Respect is important, and it goes both ways.","존중은 중요하고 서로 마찬가지야."],
  ["I wouldn't count on it.","그걸 기대하진 않을 거야.","The weather might improve, but I wouldn't count on it.","날씨가 좋아질 수도 있지만 기대하진 않을 거야."],
  ["That's not entirely accurate.","그건 완전히 정확하지는 않아.","The description is not entirely accurate.","그 설명은 완전히 정확하지는 않아."],
  ["Let's put things into perspective.","상황을 객관적으로 바라보자.","Let's put things into perspective before making a decision.","결정하기 전에 상황을 객관적으로 바라보자."],
  ["It all comes down to this.","결국 핵심은 이거야.","It all comes down to how much time we have.","결국 우리가 시간이 얼마나 있는지가 핵심이야."],
  ["There's no point in arguing.","말다툼해 봐야 소용없어.","There's no point in arguing over something so small.","그렇게 사소한 일로 말다툼해 봐야 소용없어."],
  ["I'll give you that.","그 점은 인정할게.","I don't agree with everything, but I'll give you that.","모든 것에 동의하는 건 아니지만 그 점은 인정할게."],
  ["That's not the whole picture.","그게 전부는 아니야.","The numbers don't show the whole picture.","그 숫자만으로는 전체 상황을 알 수 없어."]

