  // DAY 110 - 자연스러운 일상 회화
  ["I'm beat.","나 완전히 지쳤어.","I'm beat. I'm going straight to bed.","나 완전히 지쳤어. 바로 자러 갈 거야."],
  ["I'm starving.","나 배고파 죽겠어.","I'm starving. Let's get something to eat.","나 배고파 죽겠어. 뭐 좀 먹으러 가자."],
  ["I'm freezing.","나 너무 추워.","I'm freezing. Can you turn up the heat?","나 너무 추워. 난방 좀 올려 줄래?"],
  ["I'm swamped.","나 일이 너무 많아.","I'm swamped with work this week.","이번 주에 일이 너무 많아."],
  ["I'm broke.","나 돈이 하나도 없어.","I can't go shopping. I'm broke.","쇼핑하러 못 가. 나 돈이 하나도 없어."],
  ["I'm exhausted.","나 완전히 녹초가 됐어.","I'm exhausted after that long trip.","긴 여행을 마치고 완전히 녹초가 됐어."],
  ["I'm dead serious.","나 정말 진지해.","I'm dead serious. I'm not joking.","나 정말 진지해. 농담하는 거 아니야."],
  ["You nailed it.","정말 잘했어.","Your presentation was amazing. You nailed it!","발표 정말 훌륭했어. 완벽하게 해냈네!"],
  ["That hit the spot.","딱 좋았어.","That cold drink really hit the spot.","그 시원한 음료가 정말 딱 좋았어."],
  ["I'm not feeling it.","별로 내키지 않아.","I'm not feeling it today. Maybe tomorrow.","오늘은 별로 내키지 않아. 내일은 어떨까."],
  ["It's growing on me.","점점 좋아지고 있어.","I didn't like the song at first, but it's growing on me.","처음에는 그 노래가 별로였는데 점점 좋아지고 있어."],
  ["I'm getting the hang of it.","이제 요령을 익히고 있어.","I'm getting the hang of driving.","운전하는 요령을 이제 익히고 있어."],
  ["Give it a shot.","한번 해 봐.","You've never tried it? Give it a shot.","한 번도 안 해 봤어? 한번 해 봐."],
  ["Hang in there.","조금만 더 힘내.","I know it's difficult, but hang in there.","힘든 거 알지만 조금만 더 힘내."],
  ["Take it easy.","무리하지 마, 편하게 해.","You've been working hard. Take it easy.","열심히 일했잖아. 이제 좀 쉬어."],
  ["My lips are sealed.","비밀로 할게.","Don't worry. My lips are sealed.","걱정하지 마. 비밀로 할게."],
  ["It's a piece of cake.","식은 죽 먹기야.","The test was a piece of cake.","시험은 식은 죽 먹기였어."],
  ["I'm all ears.","잘 듣고 있어.","Tell me what happened. I'm all ears.","무슨 일이 있었는지 말해 봐. 잘 듣고 있어."],
  ["You read my mind.","내 마음을 읽었네.","I was thinking the same thing. You read my mind.","나도 같은 생각을 하고 있었어. 내 마음을 읽었네."],
  ["That makes two of us.","나도 그래.","I hate getting up early. That makes two of us.","나는 일찍 일어나는 게 싫어. 나도 그래."],
  ["Don't hold your breath.","기대하지 않는 게 좋을 거야.","He might apologize, but don't hold your breath.","그가 사과할 수도 있지만 너무 기대하지는 마."],
  ["It's not my cup of tea.","내 취향은 아니야.","Horror movies are not my cup of tea.","공포 영화는 내 취향이 아니야."],
  ["I'm game.","나도 좋아, 할래.","If you want to go hiking, I'm game.","등산 가고 싶으면 나도 좋아."],
  ["Count me out.","나는 빼 줘.","I'm not interested in the competition. Count me out.","나는 그 대회에 관심 없어. 나는 빼 줘."],
  ["You bet.","당연하지.","Can I count on you? You bet.","너 믿어도 돼? 당연하지."],
  ["No kidding!","정말?","You met your favorite actor? No kidding!","좋아하는 배우를 만났다고? 정말?"],
  ["For real?","진짜로?","You're moving next month? For real?","다음 달에 이사한다고? 진짜로?"],
  ["You've got to be kidding me.","농담이지?","The flight was canceled? You've got to be kidding me.","비행기가 취소됐다고? 농담이지?"],
  ["I can't even.","정말 말도 안 나와.","That was so embarrassing. I can't even.","정말 너무 창피했어. 말도 안 나와."],
  ["What a mess!","정말 엉망이네!","Look at this room. What a mess!","이 방 좀 봐. 정말 엉망이네!"],
  ["Here we go.","자, 시작하자.","Everyone is ready. Here we go!","모두 준비됐어. 자, 시작하자!"],
  ["There you go.","바로 그거야, 여기 있어.","That's how you do it. There you go!","바로 그렇게 하는 거야. 잘했어!"],
  ["I knew it!","그럴 줄 알았어!","I knew it! I was right all along.","그럴 줄 알았어! 처음부터 내가 맞았잖아."],
  ["It figures.","그럴 줄 알았어.","The store is closed today. It figures.","오늘 가게가 문을 닫았네. 그럴 줄 알았어."],
  ["That's the spirit!","바로 그런 자세야!","You can do it. That's the spirit!","넌 할 수 있어. 바로 그런 자세야!"],
  ["Don't tempt me.","나 유혹하지 마.","Chocolate cake? Don't tempt me.","초콜릿 케이크라고? 나 유혹하지 마."],
  ["I'm sold.","완전히 마음에 들었어.","After seeing the photos, I'm sold.","사진을 보고 완전히 마음이 끌렸어."],
  ["It's a deal.","좋아, 그렇게 하자.","You help me today, and I'll help you tomorrow. It's a deal.","오늘 네가 나를 도와주면 내일 내가 도와줄게. 좋아, 그렇게 하자."],
  ["Fair enough.","그 말도 일리가 있어.","You need more time? Fair enough.","시간이 더 필요하다고? 그 말도 일리가 있어."],
  ["Let's wrap it up.","이제 마무리하자.","We've done enough for today. Let's wrap it up.","오늘은 충분히 했어. 이제 마무리하자."]

