  ["international treaty","국제 조약","The treaty was signed by several countries.","그 조약은 여러 국가에 의해 서명됐어."],

  // DAY 189 - 의학과 인체 과학
  ["cardiovascular system","심혈관계","Exercise improves cardiovascular health.","운동은 심혈관 건강을 개선해."],
  ["respiratory system","호흡계","The respiratory system brings oxygen into the body.","호흡계는 산소를 몸속으로 들여보내."],
  ["nervous system","신경계","The nervous system controls many body functions.","신경계는 신체의 많은 기능을 조절해."],
  ["circulatory system","순환계","The circulatory system transports blood throughout the body.","순환계는 몸 전체에 혈액을 운반해."],
  ["digestive tract","소화관","Food travels through the digestive tract.","음식은 소화관을 따라 이동해."],
  ["endocrine system","내분비계","The endocrine system produces hormones.","내분비계는 호르몬을 생성해."],
  ["lymphatic system","림프계","The lymphatic system helps fight infection.","림프계는 감염과 싸우는 데 도움을 줘."],
  ["spinal cord","척수","The spinal cord carries signals between the brain and body.","척수는 뇌와 신체 사이에 신호를 전달해."],
  ["brain stem","뇌간","The brain stem controls essential functions such as breathing.","뇌간은 호흡과 같은 필수 기능을 조절해."],
  ["cerebral cortex","대뇌 피질","The cerebral cortex is involved in complex thinking.","대뇌 피질은 복잡한 사고에 관여해."],
  ["neuron","뉴런, 신경 세포","A neuron transmits electrical and chemical signals.","뉴런은 전기적·화학적 신호를 전달해."],
  ["synapse","시냅스","A synapse connects one neuron to another.","시냅스는 한 신경 세포를 다른 신경 세포와 연결해."],
  ["nerve impulse","신경 자극","A nerve impulse travels along the neuron.","신경 자극은 신경 세포를 따라 이동해."],
  ["hormone","호르몬","Hormones regulate many processes in the body.","호르몬은 신체의 많은 과정을 조절해."],
  ["insulin","인슐린","Insulin helps regulate blood sugar levels.","인슐린은 혈당 수치를 조절하는 데 도움을 줘."],
  ["metabolism","신진대사","Metabolism converts food into energy.","신진대사는 음식을 에너지로 전환해."],
  ["bloodstream","혈류","The medicine enters the bloodstream quickly.","그 약은 혈류로 빠르게 들어가."],
  ["red blood cell","적혈구","Red blood cells carry oxygen.","적혈구는 산소를 운반해."],
  ["white blood cell","백혈구","White blood cells help defend the body against infection.","백혈구는 감염으로부터 몸을 보호하는 데 도움을 줘."],
  ["platelet","혈소판","Platelets help blood clot.","혈소판은 혈액 응고를 도와."],
  ["blood clot","혈전","A blood clot can block a blood vessel.","혈전은 혈관을 막을 수 있어."],
  ["blood pressure","혈압","Regular exercise can help control blood pressure.","규칙적인 운동은 혈압 조절에 도움이 될 수 있어."],
  ["heart rate","심박수","Your heart rate increases during exercise.","운동 중에는 심박수가 증가해."],
  ["oxygen saturation","산소 포화도","The device measures oxygen saturation.","그 기기는 산소 포화도를 측정해."],
  ["inflammation","염증","Inflammation is part of the body's immune response.","염증은 신체 면역 반응의 일부야."],
  ["chronic condition","만성 질환","People with a chronic condition may need regular care.","만성 질환이 있는 사람은 정기적인 관리가 필요할 수 있어."],
  ["acute infection","급성 감염","The patient was diagnosed with an acute infection.","그 환자는 급성 감염 진단을 받았어."],
  ["autoimmune disease","자가면역 질환","An autoimmune disease affects the immune system.","자가면역 질환은 면역 체계에 영향을 줘."],
  ["genetic disorder","유전 질환","Some genetic disorders are inherited from parents.","일부 유전 질환은 부모에게서 물려받아."],
  ["clinical trial","임상 시험","The new treatment is undergoing a clinical trial.","새로운 치료법은 임상 시험을 진행 중이야."],
  ["placebo","위약","Some participants received a placebo.","일부 참가자들은 위약을 받았어."],
  ["double-blind study","이중 맹검 연구","The treatment was tested in a double-blind study.","그 치료법은 이중 맹검 연구에서 시험됐어."],
  ["medical imaging","의료 영상","Medical imaging helps doctors examine internal organs.","의료 영상은 의사들이 내부 장기를 검사하는 데 도움을 줘."],
  ["ultrasound","초음파","The doctor used an ultrasound to examine the abdomen.","의사는 복부를 검사하기 위해 초음파를 사용했어."],
  ["magnetic resonance imaging","자기공명영상, MRI","Magnetic resonance imaging provides detailed images of soft tissue.","자기공명영상은 연조직의 상세한 영상을 제공해."],
  ["biopsy","생검","The doctor recommended a biopsy for further examination.","의사는 추가 검사를 위해 생검을 권했어."],
  ["pathology","병리학","Pathology examines the causes and effects of disease.","병리학은 질병의 원인과 영향을 연구해."],
  ["prognosis","예후","The doctor discussed the patient's prognosis.","의사는 환자의 예후에 대해 설명했어."],
  ["rehabilitation","재활","Physical rehabilitation helped him regain mobility.","물리 재활 치료는 그가 움직임을 회복하는 데 도움을 줬어."],
  ["preventive medicine","예방 의학","Preventive medicine focuses on avoiding disease.","예방 의학은 질병을 예방하는 데 중점을 둬."],

  // DAY 190 - 자연스러운 고급 회화
  ["I see your point.","네 말이 무슨 뜻인지 알겠어.","I see your point, but I still disagree.","네 말이 무슨 뜻인지는 알겠지만 여전히 동의하지 않아."],
  ["That's not what I meant.","내가 그런 뜻으로 말한 건 아니야.","Sorry, that's not what I meant.","미안해. 내가 그런 뜻으로 말한 건 아니야."],
  ["I may have misunderstood.","내가 잘못 이해했을 수도 있어.","I may have misunderstood what you said earlier.","아까 네가 한 말을 내가 잘못 이해했을 수도 있어."],
  ["I wouldn't read too much into it.","그렇게 깊게 해석하지는 않을 거야.","He didn't reply right away. I wouldn't read too much into it.","그가 바로 답하지 않았어. 너무 깊게 해석하지는 않을 거야."],
  ["That's not set in stone.","그건 확정된 게 아니야.","The schedule is flexible. It's not set in stone.","일정은 유동적이야. 확정된 건 아니야."],
  ["Let's keep things in perspective.","상황을 객관적으로 보자.","It's disappointing, but let's keep things in perspective.","실망스럽지만 상황을 객관적으로 보자."],
  ["I have to hand it to you.","네 실력은 인정해야겠어.","I have to hand it to you. You handled that really well.","네 실력은 인정해야겠어. 그 일을 정말 잘 처리했어."],
  ["You can't win them all.","모든 일에서 이길 수는 없어.","We lost this time, but you can't win them all.","이번에는 졌지만 모든 일에서 이길 수는 없어."],
  ["That's a whole other matter.","그건 완전히 별개의 문제야.","Whether we can afford it is a whole other matter.","우리가 그걸 감당할 수 있는지는 완전히 별개의 문제야."],
  ["I'm getting mixed signals.","상대의 태도가 헷갈려.","I'm getting mixed signals from him.","그의 태도가 헷갈려."],
  ["I don't want to jump to conclusions.","성급하게 결론 내리고 싶지 않아.","Let's wait for more information. I don't want to jump to conclusions.","정보를 더 기다리자. 성급하게 결론 내리고 싶지 않아."],
  ["It slipped through the cracks.","그게 실수로 누락됐어.","Your application must have slipped through the cracks.","네 신청서가 실수로 누락된 게 분명해."],
  ["Let's take a step back.","잠깐 한발 물러서서 생각해 보자.","We're getting nowhere. Let's take a step back.","우리는 진전이 없어. 잠깐 한발 물러서서 생각해 보자."],
  ["I'm willing to give it a shot.","한번 시도해 볼 생각이야.","I've never done this before, but I'm willing to give it a shot.","이걸 해 본 적은 없지만 한번 시도해 볼 생각이야."],
  ["It caught me off guard.","갑작스러워서 당황했어.","Her question caught me off guard.","그녀의 질문은 갑작스러워서 나를 당황하게 했어."],
  ["I didn't see that coming.","그럴 줄은 몰랐어.","The ending was so unexpected. I didn't see that coming.","결말이 정말 예상 밖이었어. 그럴 줄은 몰랐어."],
  ["That's not a hill I'm willing to die on.","그 문제로 끝까지 싸우고 싶지는 않아.","I have a preference, but that's not a hill I'm willing to die on.","선호하는 건 있지만 그 문제로 끝까지 싸우고 싶지는 않아."],
  ["Let's not lose sight of the goal.","목표를 잊지 말자.","Things are getting complicated, but let's not lose sight of the goal.","일이 복잡해지고 있지만 목표를 잊지 말자."],
  ["I'm trying to wrap my head around it.","그걸 이해하려고 노력 중이야.","I'm still trying to wrap my head around the new system.","나는 아직 새로운 시스템을 이해하려고 노력 중이야."],
  ["It goes without saying.","말할 필요도 없이 당연하지.","It goes without saying that safety comes first.","안전이 우선이라는 건 말할 필요도 없이 당연해."],
  ["I'm not cut out for this.","나는 이 일에 적성이 맞지 않아.","I enjoy the idea, but I'm not cut out for this job.","그 생각은 좋지만 나는 이 일에 적성이 맞지 않아."],
  ["That's a tough call.","어려운 결정이야.","Choosing between the two offers is a tough call.","두 제안 중 하나를 고르는 건 어려운 결정이야."],
  ["I'll take that into consideration.","그 점을 고려해 볼게.","Thanks for your feedback. I'll take that into consideration.","의견 고마워. 그 점을 고려해 볼게."],
  ["I'm inclined to agree.","동의하는 쪽이야.","After hearing the explanation, I'm inclined to agree.","설명을 듣고 나니 동의하는 쪽이야."],
  ["I beg to differ on that.","그 점에 대해서는 의견이 달라.","I understand your argument, but I beg to differ on that.","네 주장은 이해하지만 그 점에 대해서는 의견이 달라."],
  ["That remains to be seen.","그건 두고 봐야 알겠어.","Whether the plan will work remains to be seen.","그 계획이 성공할지는 두고 봐야 알겠어."],
  ["I'm not holding it against you.","그 일로 너를 원망하지는 않아.","You made a mistake, but I'm not holding it against you.","네가 실수했지만 그 일로 너를 원망하지는 않아."],
  ["Let's call a spade a spade.","있는 그대로 솔직하게 말하자.","Let's call a spade a spade. The project failed.","있는 그대로 솔직하게 말하자. 그 프로젝트는 실패했어."],
  ["I wouldn't put it past him.","그 사람이라면 그러고도 남아.","He has a strange sense of humor. I wouldn't put it past him.","그는 유머 감각이 특이해. 그 사람이라면 그러고도 남아."],
  ["That's music to my ears.","정말 반가운 소식이야.","You got the job? That's music to my ears!","취업했다고? 정말 반가운 소식이야!"],
  ["I'm all for it.","난 적극 찬성이야.","If you want to try something new, I'm all for it.","새로운 걸 시도하고 싶다면 난 적극 찬성이야."],
  ["I'm on the fence about it.","아직 결정하지 못했어.","I'm on the fence about joining the club.","그 동아리에 가입할지 아직 결정하지 못했어."],
  ["It takes one to know one.","너도 마찬가지잖아.","You say I'm stubborn? It takes one to know one.","내가 고집 세다고? 너도 마찬가지잖아."],
  ["Let's not beat around the bush.","돌려 말하지 말자.","Let's not beat around the bush. What do you really want?","돌려 말하지 말자. 네가 정말 원하는 게 뭐야?"],
  ["I have a lot on my plate.","처리해야 할 일이 많아.","I can't take on another project. I have a lot on my plate.","다른 프로젝트를 맡을 수 없어. 처리해야 할 일이 많거든."],
  ["It's not as straightforward as it seems.","겉보기만큼 간단하지 않아.","The process is not as straightforward as it seems.","그 과정은 겉보기만큼 간단하지 않아."],
  ["I'm trying to make sense of it.","그게 무슨 의미인지 이해하려고 하고 있어.","The explanation was confusing, so I'm trying to make sense of it.","설명이 혼란스러워서 그 의미를 이해하려고 하고 있어."],
  ["That's the catch.","바로 그게 문제야.","The tickets are cheap, but they aren't refundable. That's the catch.","표는 저렴하지만 환불이 안 돼. 바로 그게 문제야."],
  ["I'm not entirely convinced.","완전히 납득한 건 아니야.","The idea sounds interesting, but I'm not entirely convinced.","그 생각은 흥미롭지만 완전히 납득한 건 아니야."],
  ["Let's leave some room for flexibility.","어느 정도 여지를 남겨 두자.","We should make a plan but leave some room for flexibility.","계획을 세우되 어느 정도 여지를 남겨 두자."]

